import socket, threading, subprocess, time
class RawServer:
    def __init__(self, handler):
        self.handler=handler; self.conns=[]; self.requests=[]
        self.sock=socket.socket(); self.sock.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); self.sock.bind(("127.0.0.1",0)); self.port=self.sock.getsockname()[1]; self.sock.listen(50)
        self.thread=threading.Thread(target=self.loop,daemon=True); self.thread.start()
    def loop(self):
        idx=0
        while True:
            try: conn,addr=self.sock.accept()
            except: return
            idx+=1; self.conns.append(conn)
            threading.Thread(target=self.handle,args=(conn,idx),daemon=True).start()
    def handle(self,conn,idx):
        conn.settimeout(5)
        data=b""
        try:
            while b"\r\n\r\n" not in data:
                ch=conn.recv(4096)
                if not ch: break
                data+=ch
        except Exception: pass
        self.requests.append((idx,data))
        try: self.handler(conn,idx,data,self)
        except Exception as e: pass
        try: conn.close()
        except: pass
    def close(self):
        try:self.sock.close()
        except:pass

def resp(body=b"<html></html>", status=b"200 OK", headers=None):
    if headers is None: headers=[(b"Content-Type",b"text/html")]
    h=b"".join(k+b": "+v+b"\r\n" for k,v in headers)
    return b"HTTP/1.1 "+status+b"\r\n"+h+b"Content-Length: "+str(len(body)).encode()+b"\r\nConnection: close\r\n\r\n"+body

def run_with(handler,args,label,timeout=15):
    srv=RawServer(handler)
    a=[x.replace("{port}",str(srv.port)).replace("{base}",f"http://127.0.0.1:{srv.port}") for x in args]
    start=time.time()
    try:
        p=subprocess.run(["./executable"]+a,capture_output=True,text=True,timeout=timeout); elapsed=time.time()-start
        print(f"{label} ARGS{a} EXIT{p.returncode} elapsed={elapsed:.2f} OUT{p.stdout!r} ERR{p.stderr!r} NREQ={len(srv.requests)} REQS={[r[1] for r in srv.requests]}\n---")
    except Exception as e:
        print(label,"TIMEOUT",e,"NREQ",len(srv.requests))
    srv.close()
