import sys; sys.path.insert(0,'/tmp')
from rawserver import *
import socket
# Handler acts like HTTP proxy: record requests, respond with root HTML directly regardless target. For https targets, likely CONNECT - handle depending request bytes: if CONNECT, respond 200 Connection Established then expect TLS ClientHello (can't TLS here) just record first bytes and close
def make_proxy_handler(mode="ok"):
    def h(conn,idx,data,srv):
        srv.proxy_data.append(data)
        if mode=="ok":
            conn.sendall(resp(b'<html><a href="http://example.com/linked">x</a></html>'))
        elif mode=="close":
            pass
        elif mode=="garbage":
            conn.sendall(b"GARBAGE\r\n\r\n")
        elif mode=="auth407":
            conn.sendall(b"HTTP/1.1 407 Proxy Authentication Required\r\nProxy-Authenticate: Basic realm=x\r\nContent-Length: 0\r\nConnection: close\r\n\r\n")
        elif mode=="connect-ok-then-close":
            if data.startswith(b"CONNECT"):
                conn.sendall(b"HTTP/1.1 200 Connection Established\r\n\r\n")
                conn.settimeout(2)
                try:
                    more=conn.recv(4096); srv.proxy_data.append(b"TLSBYTES:"+more[:50])
                except: pass
            else:
                conn.sendall(resp())
    return h

def run_proxy(args,label,mode="ok"):
    # RawServer handler wrapper doesn't know srv.proxy_data until init after; patch RawServer __? We'll create manually server then set attr before run
    handler=make_proxy_handler(mode)
    srv=RawServer(handler); srv.proxy_data=[]
    a=[x.replace("{proxy}",f"127.0.0.1:{srv.port}").replace("{proxyport}",str(srv.port)) for x in args]
    start=time.time()
    try:
        p=subprocess.run(["./executable"]+a,capture_output=True,text=True,timeout=15)
        print(f"{label} ARGS{a} EXIT{p.returncode} elapsed={time.time()-start:.2f} OUT{p.stdout!r} ERR{p.stderr!r} NREQ={len(srv.requests)} PROXYDATA={srv.proxy_data}\n---")
    except Exception as e: print(label,"EXC",e,srv.proxy_data)
    srv.close()

# What proxy formats accepted?
for proxyval in ["{proxy}","http://{proxy}","https://{proxy}","127.0.0.1:{proxyport}","localhost:{proxyport}","{proxy}/path","user:pass@127.0.0.1:{proxyport}","http://user:pass@127.0.0.1:{proxyport}","invalid","127.0.0.1:99999","127.0.0.1","http://127.0.0.1:{proxyport}/"]:
    run_proxy([f"--proxy={proxyval}","http://example.com/page?x=1"],f"proxy format {proxyval}")
