    run_proxy(["--proxy={proxy}","--max-retries=2","http://example.com/"],f"proxy {mode} retries2",mode=mode)
# no proxy for localhost? Root local real URL with proxy pointing at raw server - proxy responds html, target URL in request
run_proxy(["--proxy={proxy}","http://127.0.0.1:9/dead-local"],"proxy http dead target - proxy responds ok")
# Environment proxy variables? Test later in CLI env with no --proxy and env HTTP_PROXY set to raw server using separate script
