const version = "2.11.1"

func main() {
	opts, args, err := parseCommandLine(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if opts.Help {
		fmt.Print(helpText(filepath.Base(os.Args[0])))
		return
	}
	if opts.Version {
		fmt.Println(version)
		return
	}
	if len(args) != 1 {
		fmt.Fprintln(os.Stderr, errors.New("invalid number of arguments"))
		os.Exit(1)
	}
	code, err := runChecker(opts, args[0])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	os.Exit(code)
}

