		MaxConnections:        512,
		MaxConnectionsPerHost: 512,
		MaxResponseBodySize:   10000000,
		MaxRedirections:       64,
		Timeout:               10,
		Format:                "text",
		Color:                 "auto",
	}
}

type flagKind int

const (
	kindBool flagKind = iota
	kindString
	kindStringSlice
	kindInt
	kindUint
	kindChoice
)

type flagDef struct {
	long    string
	short   rune // 0 if none
	kind    flagKind
	choices []string
	apply   func(*options, string)
	applyB  func(*options)
}

func (d *flagDef) display() string {
	if d.short != 0 {
		return fmt.Sprintf("-%c, --%s", d.short, d.long)
	}
	return "--" + d.long
}

func boolFlag(long string, short rune, f func(*options)) *flagDef {
	return &flagDef{long: long, short: short, kind: kindBool, applyB: f}
}
func strFlag(long string, short rune, f func(*options, string)) *flagDef {
	return &flagDef{long: long, short: short, kind: kindString, apply: f}
}
func sliceFlag(long string, short rune, f func(*options, string)) *flagDef {
	return &flagDef{long: long, short: short, kind: kindStringSlice, apply: f}
}
func intFlag(long string, short rune, f func(*options, string)) *flagDef {
	return &flagDef{long: long, short: short, kind: kindInt, apply: f}
}

var flagDefs []*flagDef

func init() {
	flagDefs = []*flagDef{
		strFlag("accepted-status-codes", 0, func(o *options, v string) { o.AcceptedStatusCodes = v }),
		intFlag("buffer-size", 'b', func(o *options, v string) { n, _ := strconv.ParseInt(v, 0, 64); o.BufferSize = int(n) }),
		intFlag("max-connections", 'c', func(o *options, v string) { n, _ := strconv.ParseInt(v, 0, 64); o.MaxConnections = int(n) }),
		intFlag("max-connections-per-host", 0, func(o *options, v string) { n, _ := strconv.ParseInt(v, 0, 64); o.MaxConnectionsPerHost = int(n) }),
		intFlag("max-response-body-size", 0, func(o *options, v string) { n, _ := strconv.ParseInt(v, 0, 64); o.MaxResponseBodySize = int(n) }),
		sliceFlag("exclude", 'e', func(o *options, v string) { o.Exclude = append(o.Exclude, v) }),
		sliceFlag("include", 'i', func(o *options, v string) { o.Include = append(o.Include, v) }),
		boolFlag("follow-robots-txt", 0, func(o *options) { o.FollowRobots = true }),
		boolFlag("follow-sitemap-xml", 0, func(o *options) { o.FollowSitemap = true }),
		sliceFlag("header", 0, func(o *options, v string) { o.Headers = append(o.Headers, v) }),
		boolFlag("ignore-fragments", 'f', func(o *options) { o.IgnoreFragments = true }),
		{long: "max-retries", kind: kindUint, apply: func(o *options, v string) { n, _ := strconv.ParseUint(v, 0, 64); o.MaxRetries = n }},
		strFlag("dns-resolver", 0, func(o *options, v string) { o.DNSResolver = v }),
		{long: "format", kind: kindChoice, choices: []string{"text", "json", "junit"}, apply: func(o *options, v string) { o.Format = v }},
		boolFlag("json", 0, func(o *options) { o.JSONFlag = true }),
		boolFlag("experimental-verbose-json", 0, func(o *options) { o.ExpVerboseJSON = true }),
		boolFlag("junit", 0, func(o *options) { o.JUnitFlag = true }),
		intFlag("max-redirections", 'r', func(o *options, v string) { n, _ := strconv.ParseInt(v, 0, 64); o.MaxRedirections = int(n) }),
		intFlag("rate-limit", 0, func(o *options, v string) { n, _ := strconv.ParseInt(v, 0, 64); o.RateLimit = int(n) }),
		intFlag("timeout", 't', func(o *options, v string) { n, _ := strconv.ParseInt(v, 0, 64); o.Timeout = int(n) }),
		boolFlag("verbose", 'v', func(o *options) { o.Verbose = true }),
		strFlag("proxy", 0, func(o *options, v string) { o.Proxy = v }),
		boolFlag("skip-tls-verification", 0, func(o *options) { o.SkipTLS = true }),
		boolFlag("one-page-only", 0, func(o *options) { o.OnePageOnly = true }),
		{long: "color", kind: kindChoice, choices: []string{"auto", "always", "never"}, apply: func(o *options, v string) { o.Color = v }},
		boolFlag("help", 'h', func(o *options) { o.Help = true }),
		boolFlag("version", 0, func(o *options) { o.Version = true }),
	}
}

func findLong(name string) *flagDef {
	for _, d := range flagDefs {
		if d.long == name {
			return d
		}
	}
	return nil
}
func findShort(r rune) *flagDef {
	for _, d := range flagDefs {
		if d.short != 0 && d.short == r {
			return d
		}
	}
	return nil
}

func (d *flagDef) setValue(o *options, v string) error {
	switch d.kind {
	case kindInt:
		if _, err := strconv.ParseInt(v, 0, 64); err != nil {
			return fmt.Errorf("invalid argument for flag `%s' (expected int): %v", d.display(), err)
		}
	case kindUint:
		if _, err := strconv.ParseUint(v, 0, 64); err != nil {
			return fmt.Errorf("invalid argument for flag `%s' (expected uint): %v", d.display(), err)
		}
	case kindChoice:
		ok := false
		for _, c := range d.choices {
			if v == c {
				ok = true
				break
			}
		}
		if !ok {
			return fmt.Errorf("Invalid value `%s' for option `%s'. Allowed values are: %s", v, d.display(), formatChoices(d.choices))
		}
	}
	d.apply(o, v)
	return nil
}

func formatChoices(c []string) string {
	if len(c) == 3 {
		return c[0] + ", " + c[1] + " or " + c[2]
	}
	return strings.Join(c, ", ")
}

func isOptionToken(s string) bool {
	if len(s) < 2 || s[0] != '-' {
		return false
	}
	if strings.HasPrefix(s, "---") {
		return false
	}
	return true
}

func looksLikeNegativeNumber(s string) bool {
	if len(s) < 2 || s[0] != '-' {
		return false
	}
	// Allow -1, -0x10, -010 etc. by attempting base-0 parse.
	_, err := strconv.ParseInt(s, 0, 64)
	return err == nil
}

func parseCommandLine(argv []string) (*options, []string, error) {
	_ = os.Args
	opts := defaultOptions()
	var positional []string
	terminated := false
	for i := 0; i < len(argv); i++ {
		arg := argv[i]
		if terminated {
			positional = append(positional, arg)
			continue
		}
		if arg == "--" {
			terminated = true
			continue
		}
		if strings.HasPrefix(arg, "---") || arg == "-" || !strings.HasPrefix(arg, "-") {
			positional = append(positional, arg)
			continue
		}
		if strings.HasPrefix(arg, "--") {
			rest := arg[2:]
			name := rest
			value := ""
			hasValue := false
			if eq := strings.Index(rest, "="); eq >= 0 {
				name = rest[:eq]
				value = rest[eq+1:]
				hasValue = true
			}
			def := findLong(name)
			if def == nil {
				return nil, nil, fmt.Errorf("unknown flag `%s'", name)
			}
			if def.kind == kindBool {
				if hasValue {
					return nil, nil, fmt.Errorf("bool flag `%s' cannot have an argument", def.display())
				}
				def.applyB(opts)
				continue
			}
			if !hasValue {
				if i+1 >= len(argv) {
					return nil, nil, fmt.Errorf("expected argument for flag `%s'", def.display())
				}
				next := argv[i+1]
				if isOptionToken(next) && !(def.kind == kindInt && looksLikeNegativeNumber(next)) && !(def.kind == kindUint && looksLikeNegativeNumber(next)) {
					return nil, nil, fmt.Errorf("expected argument for flag `%s', but got option `%s'", def.display(), next)
				}
				i++
				value = next
			}
			if err := def.setValue(opts, value); err != nil {
				return nil, nil, err
			}
			continue
		}
		// Short cluster.
		cluster := arg[1:]
		runes := []rune(cluster)
		consumedArg := false
		for idx, r := range runes {
			def := findShort(r)
			if def == nil {
				return nil, nil, fmt.Errorf("unknown flag `%c'", r)
			}
			if def.kind == kindBool {
				if idx == 0 {
					rest := cluster[utf8.RuneLen(r):]
					if strings.HasPrefix(rest, "=") {
						return nil, nil, fmt.Errorf("bool flag `%s' cannot have an argument", def.display())
					}
				}
				def.applyB(opts)
				continue
			}
			// Requires a value.
			if idx == 0 {
				rest := cluster[utf8.RuneLen(r):]
				if rest != "" {
					v := rest
					if strings.HasPrefix(v, "=") {
						v = v[1:]
					}
					if err := def.setValue(opts, v); err != nil {
						return nil, nil, err
					}
				} else {
					if i+1 >= len(argv) {
						return nil, nil, fmt.Errorf("expected argument for flag `%s'", def.display())
					}
					next := argv[i+1]
					if isOptionToken(next) && !(def.kind == kindInt && looksLikeNegativeNumber(next)) && !(def.kind == kindUint && looksLikeNegativeNumber(next)) {
						return nil, nil, fmt.Errorf("expected argument for flag `%s', but got option `%s'", def.display(), next)
					}
					i++
					if err := def.setValue(opts, next); err != nil {
						return nil, nil, err
					}
				}
			} else if idx == len(runes)-1 {
				if i+1 >= len(argv) {
					return nil, nil, fmt.Errorf("expected argument for flag `%s'", def.display())
				}
				next := argv[i+1]
				if isOptionToken(next) && !(def.kind == kindInt && looksLikeNegativeNumber(next)) && !(def.kind == kindUint && looksLikeNegativeNumber(next)) {
					return nil, nil, fmt.Errorf("expected argument for flag `%s', but got option `%s'", def.display(), next)
				}
				i++
				if err := def.setValue(opts, next); err != nil {
					return nil, nil, err
				}
			} else {
				return nil, nil, fmt.Errorf("expected argument for flag `%s'", def.display())
			}
			consumedArg = true
			break
		}
		_ = consumedArg
	}
	return opts, positional, nil
}
EOF
