{"command":"cat <<'EOF' > common.go
package main

import (
	"errors"
	"fmt"
	"net/url"
	"regexp"
	"strconv"
	"strings"
)

// Status code set.
type statusRange struct{ lo, hi int } // [lo,hi) for ranges; single codes stored separately

type statusSet struct {
	singles map[int]bool
	ranges  []statusRange
}

func parseStatusSet(s string) (*statusSet, error) {
	set := &statusSet{singles: map[int]bool{}}
	for _, part := range strings.Split(s, ",") {
		if strings.Contains(part, "..") {
			pieces := strings.Split(part, "..")
			if len(pieces) != 2 {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			lo, err := strconv.Atoi(pieces[0])
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", pieces[0])
			}
			hi, err := strconv.Atoi(pieces[1])
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", pieces[1])
			}
			set.ranges = append(set.ranges, statusRange{lo, hi})
		} else {
			n, err := strconv.Atoi(part)
			if err != nil {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			set.singles[n] = true
		}
	}
	return set, nil
}

func (s *statusSet) contains(code int) bool {
	if s.singles[code] {
		return true
	}
	for _, r := range s.ranges {
		if code >= r.lo && code < r.hi {
			return true
		}
	}
	return false
}

// Link filter.
type linkFilter struct {
	exclude []*regexp.Regexp
	include []*regexp.Regexp
}

func compilePatterns(patterns []string) ([]*regexp.Regexp, error) {
	out := make([]*regexp.Regexp, 0, len(patterns))
	for _, p := range patterns {
		re, err := regexp.Compile(p)
		if err != nil {
			return nil, err
		}
		out = append(out, re)
	}
	return out, nil
}

func (f *linkFilter) isValid(u *url.URL) bool {
	s := u.String()
	if len(f.include) > 0 {
		ok := false
		for _, re := range f.include {
			if re.MatchString(s) {
				ok = true
				break
			}
		}
		if !ok {
			return false
		}
	}
	for _, re := range f.exclude {
		if re.MatchString(s) {
			return false
		}
	}
	return true
}

// Headers.
type headerPair struct {
	key   string
	value string
}

func parseHeaders(raw []string) ([]headerPair, error) {
	out := make([]headerPair, 0, len(raw))
	for _, h := range raw {
		idx := strings.Index(h, ":")
		if idx < 0 {
			return nil, errors.New("invalid header format")
		}
