{"command":"cat <<'EOF' > html.go
package main

import (
	"net/url"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type linkCandidate struct {
	url *url.URL // non-nil for a successfully parsed link
	raw string   // for invalid links: trimmed raw text
	err error    // for invalid links: parse error
}

type pageData struct {
	links []linkCandidate
	ids   map[string]bool
}

type tagAttr struct {
	key string
	val string
}

type startTag struct {
	name        string
	attrs       []tagAttr
	selfClosing bool
	foreign     bool
}

func (t *startTag) attr(key string) (string, bool) {
	for _, a := range t.attrs {
		k := a.key
		if t.foreign && k == "xlink:href" {
			k = "href"
		}
		if k == key {
			return a.val, true
		}
	}
	return "", false
}

var voidElements = map[string]bool{
	"area": true, "base": true, "br": true, "col": true, "embed": true,
	"hr": true, "img": true, "input": true, "link": true, "meta": true,
	"param": true, "source": true, "track": true, "wbr": true,
}

var rawTextElements = map[string]bool{
	"script": true, "style": true, "textarea": true, "title": true,
	"xmp": true, "iframe": true, "noembed": true, "noframes": true,
	"noscript": true,
}

func isHTMLSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\f' || b == '\r'
}
func isASCIILetter(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}
func lowerASCII(s string) string {
	has := false
	for i := 0; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' {
			has = true
			break
		}
	}
	if !has {
		return s
	}
	b := []byte(s)
	for i, c := range b {
		if c >= 'A' && c <= 'Z' {
			b[i] = c + 32
		}
	}
	return string(b)
}

func normalizeNewlines(s string) string {
	if !strings.Contains(s, "\r") {
		return s
	}
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	return s
}

// decodeEntities decodes character references in an attribute value.
// Input is treated as raw bytes in a Go string (invalid UTF-8 preserved
// except where an entity expands to UTF-8).
func decodeEntities(s string) string {
	if !strings.Contains(s, "&") {
		return strings.ReplaceAll(s, "\x00", "\uFFFD")
	}
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); {
		c := s[i]
		if c == 0 {
			b.WriteString("\uFFFD")
			i++
			continue
		}
		if c != '&' {
			b.WriteByte(c)
			i++
			continue
		}
		// Numeric character reference.
		if i+1 < len(s) && s[i+1] == '#' {
			j := i + 2
			hex := false
			if j < len(s) && (s[j] == 'x' || s[j] == 'X') {
				hex = true
				j++
			}
			start := j
			var val int64
			overflow := false
			for j < len(s) {
				d := s[j]
				var dig int64
				if hex {
					switch {
					case d >= '0' && d <= '9':
						dig = int64(d - '0')
					case d >= 'a' && d <= 'f':
						dig = int64(d-'a') + 10
					case d >= 'A' && d <= 'F':
						dig = int64(d-'A') + 10
					default:
						goto numDone
					}
					val = val*16 + dig
				} else {
					if d < '0' || d > '9' {
						goto numDone
					}
					val = val*10 + int64(d-'0')
				}
				if val > 0x10FFFF*2 {
					overflow = true
				}
				j++
			}
		numDone:
			if j == start {
				b.WriteByte('&')
				i++
				continue
			}
			if j < len(s) && s[j] == ';' {
				j++
			}
			if overflow {
				val = 0x110000
			}
			b.WriteString(htmlNumericRefRune(val))
			i = j
			continue
		}
		// Named character reference: longest match.
		bestLen := 0
		bestVal := ""
		maxLen := len(s) - (i + 1)
		if maxLen > 64 {
			maxLen = 64
		}
		for L := 1; L <= maxLen; L++ {
			cand := s[i+1 : i+1+L]
			if v, ok := htmlEntities[cand]; ok {
				bestLen = L
				bestVal = v
			}
			// Entity names consist of alphanumerics and a trailing ';'.
			ch := s[i+L]
			if !(ch >= '0' && ch <= '9' || ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z' || ch == ';') {
				break
			}
			if ch == ';' && L >= 1 {
				// A match including this semicolon will be considered at
				// the next length; after that no further name can follow.
				if L+1 <= maxLen {
					if v, ok := htmlEntities[s[i+1:i+1+L+1]]; ok {
						bestLen = L + 1
						bestVal = v
					}
				}
				break
			}
		}
		if bestLen == 0 {
			b.WriteByte('&')
			i++
			continue
		}
		matched := s[i+1 : i+1+bestLen]
		if !strings.HasSuffix(matched, ";") {
			// Historical attribute rule: don't expand a semicolon-less
			// entity when followed by '=' or an alphanumeric.
			nextIdx := i + 1 + bestLen
			if nextIdx < len(s) {
				nb := s[nextIdx]
				if nb == '=' || nb >= '0' && nb <= '9' || nb >= 'a' && nb <= 'z' || nb >= 'A' && nb <= 'Z' {
					b.WriteByte('&')
					i++
					continue
				}
			}
		}
		b.WriteString(bestVal)
		i = i + 1 + bestLen
	}
	return b.String()
}

var c1Replacement = map[int64]rune{
	0x80: 0x20AC, 0x82: 0x201A, 0x83: 0x0192, 0x84: 0x201E, 0x85: 0x2026,
	0x86: 0x2020, 0x87: 0x2021, 0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160,
	0x8B: 0x2039, 0x8C: 0x0152, 0x8E: 0x017D, 0x91: 0x2018, 0x92: 0x2019,
	0x93: 0x201C, 0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
	0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A, 0x9C: 0x0153,
	0x9E: 0x017E, 0x9F: 0x0178,
}

func htmlNumericRefRune(v int64) string {
	if v == 0 || v > 0x10FFFF || v >= 0xD800 && v <= 0xDFFF {
		return "\uFFFD"
	}
	if r, ok := c1Replacement[v]; ok {
		return string(r)
	}
	return string(rune(v))
}

var _ = strconv.Itoa

// Tokenizer.
type htmlTokenizer struct {
	s     string
	pos   int
	stack []stackElem
}
type stackElem struct {
	name    string
	foreign bool
	attrs   []tagAttr
}

func (e stackElem) attr(key string) string {
	for _, a := range e.attrs {
		if a.key == key {
			return a.val
		}
	}
	return ""
}

func (tz *htmlTokenizer) inForeign() bool {
	if len(tz.stack) == 0 {
		return false
	}
	top := tz.stack[len(tz.stack)-1]
	if !top.foreign {
		return false
	}
	// HTML integration points / text integration points: children are HTML.
	switch top.name {
	case "foreignobject", "desc", "title":
		return false
	case "mi", "mo", "mn", "ms", "mtext":
		return false
	case "annotation-xml":
		enc := lowerASCII(top.attr("encoding"))
		if enc == "text/html" || enc == "application/xhtml+xml" {
			return false
		}
	}
	return true
}

func (tz *htmlTokenizer) popTo(name string) {
	for i := len(tz.stack) - 1; i >= 0; i-- {
		if tz.stack[i].name == name {
			tz.stack = tz.stack[:i]
			return
		}
	}
}

// skipToGT consumes through the next '>' respecting quotes; returns false at EOF.
func (tz *htmlTokenizer) skipToGT() bool {
	var quote byte
	for tz.pos < len(tz.s) {
		c := tz.s[tz.pos]
		tz.pos++
		if quote != 0 {
			if c == quote {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			continue
		}
		if c == '>' {
			return true
		}
	}
	return false
}

func (tz *htmlTokenizer) skipBogusComment() {
	idx := strings.IndexByte(tz.s[tz.pos:], '>')
	if idx < 0 {
		tz.pos = len(tz.s)
		return
	}
	tz.pos += idx + 1
}

func (tz *htmlTokenizer) skipComment() {
	// pos is just after "<!--".
	if strings.HasPrefix(tz.s[tz.pos:], ">") {
		tz.pos++
		return
	}
	if strings.HasPrefix(tz.s[tz.pos:], "->") {
		tz.pos += 2
		return
	}
	end := -1
	endLen := 0
	if i := strings.Index(tz.s[tz.pos:], "-->"); i >= 0 {
		end = i
		endLen = 3
	}
	if i := strings.Index(tz.s[tz.pos:], "--!>"); i >= 0 && (end < 0 || i < end) {
		end = i
		endLen = 4
	}
	if end < 0 {
		tz.pos = len(tz.s)
		return
	}
	tz.pos += end + endLen
}

func (tz *htmlTokenizer) findRawClose(name string) int {
	// Search for "</name" followed by ws, '/', '>' or EOF (case-insensitive).
	hay := tz.s[tz.pos:]
	needle := "</" + name
	for off := 0; off+len(needle) <= len(hay); {
		idx := indexFoldASCII(hay[off:], needle)
		if idx < 0 {
			return -1
		}
		pos := off + idx
		after := pos + len(needle)
		if after >= len(hay) {
			return tz.pos + pos
		}
		c := hay[after]
		if isHTMLSpace(c) || c == '/' || c == '>' {
			return tz.pos + pos
		}
		off = pos + 1
	}
	return -1
}

func indexFoldASCII(hay, needle string) int {
	for i := 0; i+len(needle) <= len(hay); i++ {
		ok := true
		for j := 0; j < len(needle); j++ {
			a, b := hay[i+j], needle[j]
			if a >= 'A' && a <= 'Z' {
				a += 32
			}
			if b >= 'A' && b <= 'Z' {
				b += 32
			}
			if a != b {
				ok = false
				break
			}
		}
		if ok {
			return i
		}
	}
	return -1
}

// next returns the next start tag, or nil at EOF.
func (tz *htmlTokenizer) next() *startTag {
	for tz.pos < len(tz.s) {
		lt := strings.IndexByte(tz.s[tz.pos:], '<')
		if lt < 0 {
			tz.pos = len(tz.s)
			return nil
		}
		tz.pos += lt
		if tz.pos+1 >= len(tz.s) {
			tz.pos = len(tz.s)
			return nil
		}
		c1 := tz.s[tz.pos+1]
		if c1 == '!' {
			if strings.HasPrefix(tz.s[tz.pos:], "<!--") {
				tz.pos += 4
				tz.skipComment()
				continue
			}
			if strings.HasPrefix(tz.s[tz.pos:], "<![CDATA[") {
				if tz.inForeign() {
					end := strings.Index(tz.s[tz.pos:], "]]>")
					if end < 0 {
						tz.pos = len(tz.s)
						return nil
					}
					tz.pos += end + 3
				} else {
					tz.pos += 2
					tz.skipBogusComment()
				}
				continue
			}
			if len(tz.s)-tz.pos >= 9 && lowerASCII(tz.s[tz.pos:tz.pos+9]) == "<!doctype" {
				tz.pos += 2
				tz.skipToGT()
				continue
			}
			tz.pos += 2
			tz.skipBogusComment()
			continue
		}
		if c1 == '?' {
			tz.pos += 2
			tz.skipBogusComment()
			continue
		}
		if c1 == '/' {
			if tz.pos+2 >= len(tz.s) {
				tz.pos = len(tz.s)
				return nil
			}
			c2 := tz.s[tz.pos+2]
			if c2 == '>' {
				tz.pos += 3
				continue
			}
			if !isASCIILetter(c2) {
				tz.pos += 2
				tz.skipBogusComment()
				continue
			}
			// End tag.
			start := tz.pos + 2
			j := start
			for j < len(tz.s) && !isHTMLSpace(tz.s[j]) && tz.s[j] != '/' && tz.s[j] != '>' {
				j++
			}
			name := lowerASCII(tz.s[start:j])
			tz.pos = j
			if !tz.skipToGT() {
				return nil
			}
			tz.popTo(name)
			continue
		}
		if !isASCIILetter(c1) {
			tz.pos++
			continue
		}
		// Start tag.
		tag := tz.parseStartTag()
		if tag == nil {
			return nil
		}
		return tag
	}
	return nil
}

func (tz *htmlTokenizer) parseStartTag() *startTag {
	// pos at '<', next is a letter.
	foreignCtx := tz.inForeign()
	start := tz.pos + 1
	j := start
	for j < len(tz.s) && !isHTMLSpace(tz.s[j]) && tz.s[j] != '/' && tz.s[j] != '>' {
		j++
	}
	name := lowerASCII(tz.s[start:j])
	if !foreignCtx && name == "image" {
		name = "img"
	}
	tag := &startTag{name: name}
	// Foreign-ness of this element.
	if foreignCtx {
		tag.foreign = true
	} else if name == "svg" || name == "math" {
		tag.foreign = true
	}
	tz.pos = j
	seen := map[string]bool{}
	for {
		// Before attribute name: skip whitespace.
		for tz.pos < len(tz.s) && isHTMLSpace(tz.s[tz.pos]) {
			tz.pos++
		}
		if tz.pos >= len(tz.s) {
			return nil
		}
		c := tz.s[tz.pos]
		if c == '>' {
			tz.pos++
			break
		}
		if c == '/' {
			if tz.pos+1 < len(tz.s) && tz.s[tz.pos+1] == '>' {
				tz.pos += 2
				tag.selfClosing = true
				break
			}
			tz.pos++
			continue
		}
		// Attribute name.
		aStart := tz.pos
		if tz.s[tz.pos] == '=' {
			tz.pos++
		}
		for tz.pos < len(tz.s) && !isHTMLSpace(tz.s[tz.pos]) && tz.s[tz.pos] != '=' && tz.s[tz.pos] != '/' && tz.s[tz.pos] != '>' {
			tz.pos++
		}
		attrName := lowerASCII(tz.s[aStart:tz.pos])
		// After attribute name.
		for tz.pos < len(tz.s) && isHTMLSpace(tz.s[tz.pos]) {
			tz.pos++
		}
		value := ""
		tagDone := false
		if tz.pos < len(tz.s) && tz.s[tz.pos] == '=' {
			tz.pos++
			for tz.pos < len(tz.s) && isHTMLSpace(tz.s[tz.pos]) {
				tz.pos++
			}
			if tz.pos >= len(tz.s) {
				return nil
			}
			q := tz.s[tz.pos]
			if q == '"' || q == '\'' {
				tz.pos++
				vStart := tz.pos
				end := strings.IndexByte(tz.s[tz.pos:], q)
				if end < 0 {
					return nil
				}
				value = tz.s[vStart : tz.pos+end]
				tz.pos += end + 1
			} else if q == '>' {
				// Missing value; the tag ends here.
				tz.pos++
				tagDone = true
			} else {
				vStart := tz.pos
				for tz.pos < len(tz.s) && !isHTMLSpace(tz.s[tz.pos]) && tz.s[tz.pos] != '>' {
					tz.pos++
				}
				if tz.pos >= len(tz.s) {
					return nil
				}
				value = tz.s[vStart:tz.pos]
			}
		}
		if attrName != "" && !seen[attrName] {
			seen[attrName] = true
			tag.attrs = append(tag.attrs, tagAttr{key: attrName, val: decodeEntities(value)})
		}
		if tagDone {
			break
		}
	}
	// Update element stack.
	acknowledgedSelfClose := tag.foreign && tag.selfClosing
	if !voidElements[tag.name] && !acknowledgedSelfClose {
		// plaintext swallows the rest of the document.
		tz.stack = append(tz.stack, stackElem{name: tag.name, foreign: tag.foreign, attrs: tag.attrs})
	}
	if tag.name == "plaintext" && !tag.foreign {
		tz.pos = len(tz.s)
		// Still return the plaintext tag itself (it carries no links).
		return tag
	}
	if !tag.foreign && rawTextElements[tag.name] {
		closeIdx := tz.findRawClose(tag.name)
		if closeIdx < 0 {
			tz.pos = len(tz.s)
		} else {
			// Leave pos at the end tag; next() will consume & pop it.
			tz.pos = closeIdx
		}
	}
	return tag
}

var metaPropertyLinks = map[string]bool{
	"og:image": true, "og:image:url": true, "og:image:secure_url": true,
	"og:video": true, "og:audio": true, "twitter:image": true,
}

func parseSrcset(value string) []string {
	var out []string
	for _, piece := range strings.Split(value, ", ") {
		p := strings.TrimSpace(piece)
		if p == "" {
			continue
		}
		// Drop the final whitespace-separated token (the descriptor), if any.
		last := -1
		for i, r := range p {
			if unicode.IsSpace(r) {
				last = i
			}
		}
		if last >= 0 {
			p = strings.TrimSpace(p[:last])
		}
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

var _ = utf8.RuneLen

func parseHTMLPage(body []byte, finalURL string, filter *linkFilter) (*pageData, error) {
	content := normalizeNewlines(string(body))
	tz := &htmlTokenizer{s: content}
	var rawLinks []string
	ids := map[string]bool{}
	baseHref := ""
	hasBase := false
	for {
		tag := tz.next()
		if tag == nil {
			break
		}
		if v, ok := tag.attr("id"); ok {
			ids[v] = true
		}
		if v, ok := tag.attr("name"); ok {
			ids[v] = true
		}
		switch tag.name {
		case "base":
			if !hasBase {
				if v, ok := tag.attr("href"); ok {
					baseHref = v
					hasBase = true
				}
			}
		case "a", "link":
			if v, ok := tag.attr("href"); ok {
				rawLinks = append(rawLinks, v)
			}
		case "img", "script", "iframe", "track":
			if v, ok := tag.attr("src"); ok {
				rawLinks = append(rawLinks, v)
			}
		case "source":
			if v, ok := tag.attr("src"); ok {
				rawLinks = append(rawLinks, v)
			}
			if v, ok := tag.attr("srcset"); ok {
				rawLinks = append(rawLinks, parseSrcset(v)...)
			}
		case "meta":
			if prop, ok := tag.attr("property"); ok && metaPropertyLinks[prop] {
				if v, ok := tag.attr("content"); ok {
					rawLinks = append(rawLinks, v)
				}
			}
		}
	}
	pageURL, err := url.Parse(finalURL)
	if err != nil {
		return nil, err
	}
	baseURL := pageURL
	if hasBase {
		b, err := pageURL.Parse(baseHref)
		if err != nil {
			return nil, err
		}
		baseURL = b
	}
	page := &pageData{ids: ids}
	seen := map[string]bool{}
	for _, raw := range rawLinks {
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			continue
		}
		u, err := baseURL.Parse(trimmed)
		if err != nil {
			key := "\x00invalid:" + trimmed
			if seen[key] {
				continue
			}
			seen[key] = true
			page.links = append(page.links, linkCandidate{raw: trimmed, err: err})
			continue
		}
		if u.Scheme != "http" && u.Scheme != "https" {
			continue
		}
		if filter != nil && !filter.isValid(u) {
			continue
		}
		key := u.String()
		if seen[key] {
			continue
		}
		seen[key] = true
		page.links = append(page.links, linkCandidate{url: u})
	}
	return page, nil
}
