package main

import (
	"net/url"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type linkCandidate struct {
	url *url.URL // non-nil for a successfully parsed link
	raw string   // for invalid links: trimmed raw text
	err error    // for invalid links: parse error
}

type pageData struct {
	links []linkCandidate
	ids   map[string]bool
}

type tagAttr struct {
	key string
	val string
}

type startTag struct {
	name        string
	attrs       []tagAttr
	selfClosing bool
	foreign     bool
}

func (t *startTag) attr(key string) (string, bool) {
	for _, a := range t.attrs {
		k := a.key
		if t.foreign && k == "xlink:href" {
			k = "href"
		}
		if k == key {
			return a.val, true
		}
	}
	return "", false
}

var voidElements = map[string]bool{
	"area": true, "base": true, "br": true, "col": true, "embed": true,
	"hr": true, "img": true, "input": true, "link": true, "meta": true,
	"param": true, "source": true, "track": true, "wbr": true,
}

var rawTextElements = map[string]bool{
	"script": true, "style": true, "textarea": true, "title": true,
	"xmp": true, "iframe": true, "noembed": true, "noframes": true,
	"noscript": true,
}

func isHTMLSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\f' || b == '\r'
}
func isASCIILetter(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}
func lowerASCII(s string) string {
	has := false
	for i := 0; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' {
			has = true
			break
		}
	}
	if !has {
		return s
	}
	b := []byte(s)
	for i, c := range b {
		if c >= 'A' && c <= 'Z' {
			b[i] = c + 32
		}
	}
	return string(b)
}

func normalizeNewlines(s string) string {
	if !strings.Contains(s, "\r") {
		return s
	}
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	return s
}

// decodeEntities decodes character references in an attribute value.
// Input is treated as raw bytes in a Go string (invalid UTF-8 preserved
// except where an entity expands to UTF-8).
func decodeEntities(s string) string {
	if !strings.Contains(s, "&") {
		return strings.ReplaceAll(s, "\x00", "\uFFFD")
	}
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); {
		c := s[i]
		if c == 0 {
			b.WriteString("\uFFFD")
			i++
			continue
		}
		if c != '&' {
			b.WriteByte(c)
			i++
			continue
		}
		// Numeric character reference.
		if i+1 < len(s) && s[i+1] == '#' {
			j := i + 2
			hex := false
			if j < len(s) && (s[j] == 'x' || s[j] == 'X') {
				hex = true
				j++
			}
			start := j
			var val int64
			overflow := false
			for j < len(s) {
				d := s[j]
				var dig int64
				if hex {
					switch {
					case d >= '0' && d <= '9':
						dig = int64(d - '0')
					case d >= 'a' && d <= 'f':
						dig = int64(d-'a') + 10
					case d >= 'A' && d <= 'F':
						dig = int64(d-'A') + 10
					default:
						goto numDone
					}
					val = val*16 + dig
				} else {
					if d < '0' || d > '9' {
						goto numDone
					}
					val = val*10 + int64(d-'0')
				}
				if val > 0x10FFFF*2 {
					overflow = true
				}
				j++
			}
		numDone:
			if j == start {
				b.WriteByte('&')
				i++
				continue
			}
			if j < len(s) && s[j] == ';' {
				j++
			}
			if overflow {
				val = 0x110000
			}
			b.WriteString(htmlNumericRefRune(val))
			i = j
			continue
		}
		// Named character reference: longest match.
		bestLen := 0
		bestVal := ""
		maxLen := len(s) - (i + 1)
		if maxLen > 64 {
			maxLen = 64
		}
		for L := 1; L <= maxLen; L++ {
			cand := s[i+1 : i+1+L]
			if v, ok := htmlEntities[cand]; ok {
				bestLen = L
				bestVal = v
			}
			// Entity names consist of alphanumerics and a trailing ';'.
			ch := s[i+L]
			if !(ch >= '0' && ch <= '9' || ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z' || ch == ';') {
				break
			}
			if ch == ';' && L >= 1 {
				// A match including this semicolon will be considered at
				// the next length; after that no further name can follow.
				if L+1 <= maxLen {
					if v, ok := htmlEntities[s[i+1:i+1+L+1]]; ok {
						bestLen = L + 1
						bestVal = v
					}
				}
				break
			}
		}
		if bestLen == 0 {
			b.WriteByte('&')
			i++
			continue
		}
		matched := s[i+1 : i+1+bestLen]
		if !strings.HasSuffix(matched, ";") {
			// Historical attribute rule: don't expand a semicolon-less
			// entity when followed by '=' or an alphanumeric.
			nextIdx := i + 1 + bestLen
			if nextIdx < len(s) {
				nb := s[nextIdx]
				if nb == '=' || nb >= '0' && nb <= '9' || nb >= 'a' && nb <= 'z' || nb >= 'A' && nb <= 'Z' {
					b.WriteByte('&')
					i++
					continue
				}
			}
		}
		b.WriteString(bestVal)
		i = i + 1 + bestLen
	}
	return b.String()
}

var c1Replacement = map[int64]rune{
