var _ = strconv.Itoa

// Tokenizer.
type htmlTokenizer struct {
	s     string
	pos   int
	stack []stackElem
}
type stackElem struct {
	name    string
	foreign bool
	attrs   []tagAttr
}

func (e stackElem) attr(key string) string {
	for _, a := range e.attrs {
		if a.key == key {
			return a.val
		}
	}
	return ""
}

func (tz *htmlTokenizer) inForeign() bool {
	if len(tz.stack) == 0 {
		return false
	}
	top := tz.stack[len(tz.stack)-1]
	if !top.foreign {
		return false
	}
	// HTML integration points / text integration points: children are HTML.
	switch top.name {
	case "foreignobject", "desc", "title":
		return false
	case "mi", "mo", "mn", "ms", "mtext":
		return false
	case "annotation-xml":
		enc := lowerASCII(top.attr("encoding"))
		if enc == "text/html" || enc == "application/xhtml+xml" {
			return false
		}
	}
	return true
}

func (tz *htmlTokenizer) popTo(name string) {
	for i := len(tz.stack) - 1; i >= 0; i-- {
		if tz.stack[i].name == name {
			tz.stack = tz.stack[:i]
			return
		}
	}
}

// skipToGT consumes through the next '>' respecting quotes; returns false at EOF.
func (tz *htmlTokenizer) skipToGT() bool {
	var quote byte
	for tz.pos < len(tz.s) {
		c := tz.s[tz.pos]
		tz.pos++
		if quote != 0 {
			if c == quote {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			continue
		}
		if c == '>' {
			return true
		}
	}
	return false
}

func (tz *htmlTokenizer) skipBogusComment() {
	idx := strings.IndexByte(tz.s[tz.pos:], '>')
	if idx < 0 {
		tz.pos = len(tz.s)
		return
	}
	tz.pos += idx + 1
}

func (tz *htmlTokenizer) skipComment() {
	// pos is just after "<!--".
	if strings.HasPrefix(tz.s[tz.pos:], ">") {
		tz.pos++
		return
	}
	if strings.HasPrefix(tz.s[tz.pos:], "->") {
		tz.pos += 2
		return
	}
	end := -1
	endLen := 0
	if i := strings.Index(tz.s[tz.pos:], "-->"); i >= 0 {
		end = i
		endLen = 3
	}
	if i := strings.Index(tz.s[tz.pos:], "--!>"); i >= 0 && (end < 0 || i < end) {
		end = i
		endLen = 4
	}
	if end < 0 {
		tz.pos = len(tz.s)
		return
	}
	tz.pos += end + endLen
}

func (tz *htmlTokenizer) findRawClose(name string) int {
	// Search for "</name" followed by ws, '/', '>' or EOF (case-insensitive).
	hay := tz.s[tz.pos:]
	needle := "</" + name
	for off := 0; off+len(needle) <= len(hay); {
		idx := indexFoldASCII(hay[off:], needle)
		if idx < 0 {
			return -1
		}
		pos := off + idx
		after := pos + len(needle)
		if after >= len(hay) {
			return tz.pos + pos
		}
		c := hay[after]
		if isHTMLSpace(c) || c == '/' || c == '>' {
			return tz.pos + pos
		}
		off = pos + 1
	}
	return -1
}

func indexFoldASCII(hay, needle string) int {
	for i := 0; i+len(needle) <= len(hay); i++ {
		ok := true
		for j := 0; j < len(needle); j++ {
			a, b := hay[i+j], needle[j]
			if a >= 'A' && a <= 'Z' {
				a += 32
			}
			if b >= 'A' && b <= 'Z' {
				b += 32
			}
			if a != b {
				ok = false
				break
			}
		}
		if ok {
			return i
		}
	}
	return -1
}

// next returns the next start tag, or nil at EOF.
func (tz *htmlTokenizer) next() *startTag {
	for tz.pos < len(tz.s) {
		lt := strings.IndexByte(tz.s[tz.pos:], '<')
		if lt < 0 {
			tz.pos = len(tz.s)
			return nil
		}
		tz.pos += lt
		if tz.pos+1 >= len(tz.s) {
			tz.pos = len(tz.s)
			return nil
		}
		c1 := tz.s[tz.pos+1]
		if c1 == '!' {
			if strings.HasPrefix(tz.s[tz.pos:], "<!--") {
				tz.pos += 4
				tz.skipComment()
				continue
			}
			if strings.HasPrefix(tz.s[tz.pos:], "<![CDATA[") {
				if tz.inForeign() {
					end := strings.Index(tz.s[tz.pos:], "]]>")
					if end < 0 {
						tz.pos = len(tz.s)
						return nil
					}
					tz.pos += end + 3
				} else {
					tz.pos += 2
					tz.skipBogusComment()
				}
				continue
			}
			if len(tz.s)-tz.pos >= 9 && lowerASCII(tz.s[tz.pos:tz.pos+9]) == "<!doctype" {
				tz.pos += 2
				tz.skipToGT()
				continue
			}
			tz.pos += 2
			tz.skipBogusComment()
			continue
		}
		if c1 == '?' {
			tz.pos += 2
			tz.skipBogusComment()
			continue
		}
		if c1 == '/' {
			if tz.pos+2 >= len(tz.s) {
				tz.pos = len(tz.s)
				return nil
			}
			c2 := tz.s[tz.pos+2]
			if c2 == '>' {
				tz.pos += 3
				continue
			}
			if !isASCIILetter(c2) {
				tz.pos += 2
				tz.skipBogusComment()
				continue
			}
			// End tag.
			start := tz.pos + 2
			j := start
