func (tz *htmlTokenizer) parseStartTag() *startTag {
	// pos at '<', next is a letter.
	foreignCtx := tz.inForeign()
	start := tz.pos + 1
	j := start
	for j < len(tz.s) && !isHTMLSpace(tz.s[j]) && tz.s[j] != '/' && tz.s[j] != '>' {
		j++
	}
	name := lowerASCII(tz.s[start:j])
	if !foreignCtx && name == "image" {
		name = "img"
	}
	tag := &startTag{name: name}
	// Foreign-ness of this element.
	if foreignCtx {
		tag.foreign = true
	} else if name == "svg" || name == "math" {
		tag.foreign = true
	}
	tz.pos = j
	seen := map[string]bool{}
	for {
		// Before attribute name: skip whitespace.
		for tz.pos < len(tz.s) && isHTMLSpace(tz.s[tz.pos]) {
			tz.pos++
		}
		if tz.pos >= len(tz.s) {
			return nil
		}
		c := tz.s[tz.pos]
		if c == '>' {
			tz.pos++
			break
		}
		if c == '/' {
			if tz.pos+1 < len(tz.s) && tz.s[tz.pos+1] == '>' {
				tz.pos += 2
				tag.selfClosing = true
				break
			}
			tz.pos++
			continue
		}
		// Attribute name.
		aStart := tz.pos
		if tz.s[tz.pos] == '=' {
			tz.pos++
		}
		for tz.pos < len(tz.s) && !isHTMLSpace(tz.s[tz.pos]) && tz.s[tz.pos] != '=' && tz.s[tz.pos] != '/' && tz.s[tz.pos] != '>' {
			tz.pos++
		}
		attrName := lowerASCII(tz.s[aStart:tz.pos])
		// After attribute name.
		for tz.pos < len(tz.s) && isHTMLSpace(tz.s[tz.pos]) {
			tz.pos++
		}
		value := ""
		tagDone := false
		if tz.pos < len(tz.s) && tz.s[tz.pos] == '=' {
			tz.pos++
			for tz.pos < len(tz.s) && isHTMLSpace(tz.s[tz.pos]) {
				tz.pos++
			}
			if tz.pos >= len(tz.s) {
				return nil
			}
			q := tz.s[tz.pos]
			if q == '"' || q == '\'' {
				tz.pos++
				vStart := tz.pos
				end := strings.IndexByte(tz.s[tz.pos:], q)
				if end < 0 {
					return nil
				}
				value = tz.s[vStart : tz.pos+end]
				tz.pos += end + 1
			} else if q == '>' {
				// Missing value; the tag ends here.
				tz.pos++
				tagDone = true
			} else {
				vStart := tz.pos
				for tz.pos < len(tz.s) && !isHTMLSpace(tz.s[tz.pos]) && tz.s[tz.pos] != '>' {
					tz.pos++
				}
				if tz.pos >= len(tz.s) {
					return nil
				}
				value = tz.s[vStart:tz.pos]
			}
		}
		if attrName != "" && !seen[attrName] {
			seen[attrName] = true
			tag.attrs = append(tag.attrs, tagAttr{key: attrName, val: decodeEntities(value)})
		}
		if tagDone {
			break
		}
	}
	// Update element stack.
	acknowledgedSelfClose := tag.foreign && tag.selfClosing
	if !voidElements[tag.name] && !acknowledgedSelfClose {
		// plaintext swallows the rest of the document.
		tz.stack = append(tz.stack, stackElem{name: tag.name, foreign: tag.foreign, attrs: tag.attrs})
	}
	if tag.name == "plaintext" && !tag.foreign {
		tz.pos = len(tz.s)
		// Still return the plaintext tag itself (it carries no links).
		return tag
	}
	if !tag.foreign && rawTextElements[tag.name] {
		closeIdx := tz.findRawClose(tag.name)
		if closeIdx < 0 {
			tz.pos = len(tz.s)
		} else {
			// Leave pos at the end tag; next() will consume & pop it.
			tz.pos = closeIdx
		}
	}
	return tag
}

var metaPropertyLinks = map[string]bool{
	"og:image": true, "og:image:url": true, "og:image:secure_url": true,
	"og:video": true, "og:audio": true, "twitter:image": true,
}

func parseSrcset(value string) []string {
	var out []string
	for _, piece := range strings.Split(value, ", ") {
		p := strings.TrimSpace(piece)
		if p == "" {
			continue
		}
		// Drop the final whitespace-separated token (the descriptor), if any.
		last := -1
		for i, r := range p {
			if unicode.IsSpace(r) {
				last = i
			}
		}
		if last >= 0 {
			p = strings.TrimSpace(p[:last])
		}
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

