// parseSitemapEntries streams XML and invokes onEntry for each <url> or
// <sitemap> element's <loc> text (last <loc> in an entry wins).
func parseSitemapEntries(body []byte, onEntry func(string)) error {
	dec := xml.NewDecoder(bytes.NewReader(body))
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
		se, ok := tok.(xml.StartElement)
		if !ok {
			continue
		}
		if se.Name.Local != "url" && se.Name.Local != "sitemap" {
			continue
		}
		var entry struct {
			Loc string `xml:"loc"`
		}
		if err := dec.DecodeElement(&entry, &se); err != nil {
			return err
		}
		onEntry(entry.Loc)
	}
