		if seen[key] {
			return
		}
		seen[key] = true
		page.links = append(page.links, linkCandidate{url: u})
	})
	if err != nil || len(page.links) == 0 {
		return nil
	}
	return page
}

// parseSitemapAllowlist collects the raw <loc> strings.
func parseSitemapAllowlist(body []byte) (map[string]bool, error) {
	set := map[string]bool{}
	err := parseSitemapEntries(body, func(loc string) {
		set[loc] = true
	})
	if err != nil {
		return nil, err
	}
	return set, nil
}
