cat <<'EOF' > robots.go
package main

import (
	"fmt"
	"strings"
)

type robotsRule struct {
	pattern string
	allow   bool
}

type robotsRules struct {
	groups map[string][]robotsRule
	order  []string // agent keys in first-seen order
}

func canonicalDirective(key string) string {
	switch key {
	case "allow":
		return "Allow"
	case "disallow":
		return "Disallow"
	case "crawl-delay":
		return "Crawl-delay"
	}
	return key
}

func parseRobots(body []byte) (*robotsRules, error) {
	text := string(body)
	text = strings.TrimPrefix(text, "\uFEFF")
	// Split on any of CRLF / CR / LF.
	text = strings.ReplaceAll(text, "\r\n", "\n")
	text = strings.ReplaceAll(text, "\r", "\n")
	lines := strings.Split(text, "\n")

	rules := &robotsRules{groups: map[string][]robotsRule{}}
	var parseErrs []string
	var currentAgents []string
	seenUA := false
	hasRule := false
	tokenNo := 1 // incremented before each token, so the first token is #2

	addAgent := func(agent string) {
		key := strings.ToLower(agent)
		if _, ok := rules.groups[key]; !ok {
			rules.groups[key] = nil
			rules.order = append(rules.order, key)
		}
	}

	for _, rawLine := range lines {
		line := rawLine
		// Strip comment portion.
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = line[:idx]
		}
		trimmed := strings.Trim(line, " \t")
		if trimmed == "" {
			tokenNo++ // one token for the blank/comment line
			continue
		}
		// Determine key and value. The key ends at the first ':' (trailing
		// spaces before the colon are significant), or, with no colon, at
		// the first whitespace.
		var keyRaw, value string
		hasColon := false
		workLine := strings.TrimLeft(line, " \t")
		if idx := strings.Index(workLine, ":"); idx >= 0 {
			hasColon = true
			keyRaw = workLine[:idx]
			value = strings.Trim(workLine[idx+1:], " \t")
		} else {
			if idx := strings.IndexAny(workLine, " \t"); idx >= 0 {
				keyRaw = workLine[:idx]
				value = strings.Trim(workLine[idx:], " \t")
			} else {
				keyRaw = workLine
				value = ""
			}
		}
		key := strings.ToLower(keyRaw)
		thisToken := tokenNo + 1
		// Advance the token counter past this line's tokens.
		if hasColon {
			tokenNo += 2 // key + colon
			if value != "" {
				tokenNo++
			}
		} else {
			tokenNo += len(strings.Fields(workLine)) + 1 // words + EOL
		}

		switch key {
		case "user-agent":
			seenUA = true
			if hasRule {
				currentAgents = nil
				hasRule = false
			}
			agent := strings.ToLower(value)
			currentAgents = append(currentAgents, agent)
			if agent != "" {
				addAgent(agent)
			}
		case "allow", "disallow", "crawl-delay":
			if !seenUA {
				parseErrs = append(parseErrs, fmt.Sprintf("%s before User-agent at token #%d.", canonicalDirective(key), thisToken))
				continue
			}
			hasRule = true
			if key == "crawl-delay" {
				continue
			}
			if value == "" {
				continue
			}
			rule := robotsRule{pattern: value, allow: key == "allow"}
			for _, agent := range currentAgents {
				if agent == "" {
					continue
				}
				rules.groups[agent] = append(rules.groups[agent], rule)
			}
		default:
			// Unknown / global directives (Sitemap, Host, ...) are ignored.
			continue
		}
	}
	if len(parseErrs) > 0 {
		return nil, fmt.Errorf("Parse error(s): \n%s\n", strings.Join(parseErrs, "\n"))
	}
	return rules, nil
}

func (r *robotsRules) isAllowed(urlPath string) bool {
	if r == nil {
		return true
	}
	const agent = "muffet"
	// Choose the most specific (longest) matching group.
	var chosen []robotsRule
	bestLen := -1
	for _, key := range r.order {
		if key == "" || key == "*" {
			continue
		}
		if strings.HasPrefix(agent, key) && len(key) > bestLen {
			bestLen = len(key)
			chosen = r.groups[key]
		}
	}
	if chosen == nil {
		if g, ok := r.groups["*"]; ok {
			chosen = g
		} else {
			return true
		}
	}
	path := strings.TrimPrefix(urlPath, "/")
	bestRuleLen := -1
	allowed := true
	for _, rule := range chosen {
		if robotsPatternMatches(rule.pattern, path) {
			if len(rule.pattern) > bestRuleLen {
				bestRuleLen = len(rule.pattern)
				allowed = rule.allow
			}
		}
	}
	return allowed
}

func robotsPatternMatches(pattern, path string) bool {
	pat := strings.TrimPrefix(pattern, "/")
	anchored := false
	if strings.HasSuffix(pat, "$") {
		anchored = true
		pat = pat[:len(pat)-1]
	}
	parts := strings.Split(pat, "*")
	pos := 0
	for i, part := range parts {
		if part == "" {
			continue
		}
		if i == 0 {
			if !strings.HasPrefix(path[pos:], part) {
				return false
			}
			pos += len(part)
			continue
		}
		idx := strings.Index(path[pos:], part)
		if idx < 0 {
			return false
		}
		pos += idx + len(part)
	}
	if anchored && pos != len(path) {
		// With a trailing '*', pos may be before the end while still
		// matching; Split produces a trailing empty part in that case.
		if !strings.HasSuffix(pat, "*") {
			return false
		}
	}
	return true
}
EOF
gofmt -w sitemap.go robots.go
