package main

import (
	"bytes"
	"encoding/xml"
	"io"
	"net/url"
)

// parseSitemapEntries streams XML and invokes onEntry for each <url> or
// <sitemap> element's <loc> text (last <loc> in an entry wins).
func parseSitemapEntries(body []byte, onEntry func(string)) error {
	dec := xml.NewDecoder(bytes.NewReader(body))
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
		se, ok := tok.(xml.StartElement)
		if !ok {
			continue
		}
		if se.Name.Local != "url" && se.Name.Local != "sitemap" {
			continue
		}
		var entry struct {
			Loc string `xml:"loc"`
		}
		if err := dec.DecodeElement(&entry, &se); err != nil {
			return err
		}
		onEntry(entry.Loc)
	}
}

// parseSitemapPage returns a page if the document yields at least one usable
// entry, otherwise nil (not a sitemap page).
func parseSitemapPage(body []byte, filter *linkFilter) *pageData {
	page := &pageData{ids: map[string]bool{}}
	seen := map[string]bool{}
	err := parseSitemapEntries(body, func(loc string) {
		u, _ := url.Parse(loc)
		// Like the reference, an unparseable loc yields a nil URL which
		// crashes inside isValid; keep that ordering.
		if filter != nil && !filter.isValid(u) {
			return
		}
		if u.Scheme != "" && u.Scheme != "http" && u.Scheme != "https" {
			return
		}
		key := u.String()
		if seen[key] {
			return
		}
		seen[key] = true
		page.links = append(page.links, linkCandidate{url: u})
	})
	if err != nil || len(page.links) == 0 {
		return nil
	}
	return page
}

// parseSitemapAllowlist collects the raw <loc> strings.
func parseSitemapAllowlist(body []byte) (map[string]bool, error) {
	set := map[string]bool{}
	err := parseSitemapEntries(body, func(loc string) {
		set[loc] = true
	})
	if err != nil {
		return nil, err
	}
	return set, nil
}
