cat <<'EOF' > httpclient.go
package main

import (
	"bufio"
	"bytes"
	"compress/gzip"
	"compress/zlib"
	"context"
	"crypto/tls"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net"
	"net/url"
	"strconv"
	"strings"
	"sync"
	"time"
)

var errTimeout = errors.New("timeout")
var errBodyTooLarge = errors.New("body size exceeds the given limit")
var errServerClosed = errors.New("the server closed connection before returning the first response byte. Make sure the server returns 'Connection: close' response header before closing the connection")

type internalRetryError struct{ err error }

func (e *internalRetryError) Error() string { return e.err.Error() }
func (e *internalRetryError) Unwrap() error { return e.err }

type rawResponse struct {
	status   int
	headers  []headerPair
	body     []byte
	finalURL string
}

func (r *rawResponse) headerFirst(name string) string {
	for _, h := range r.headers {
		if strings.EqualFold(h.key, name) {
			return h.value
		}
	}
	return ""
}
func (r *rawResponse) headerLast(name string) string {
	v := ""
	for _, h := range r.headers {
		if strings.EqualFold(h.key, name) {
			v = h.value
		}
	}
	return v
}
func (r *rawResponse) contentType() string {
	v := r.headerLast("Content-Type")
	if v == "" {
		return "text/plain; charset=utf-8"
	}
	return v
}

type dnsCall struct {
	done chan struct{}
	ips  []net.IP
	err  error
}

type webClient struct {
	opts      *options
	headers   []headerPair
	statusSet *statusSet

	globalSem chan struct{}

	hostMu   sync.Mutex
	hostSems map[string]chan struct{}

	rateMu   sync.Mutex
	rateNext time.Time

	resolver *net.Resolver
	dnsMu    sync.Mutex
	dnsCache map[string]*dnsCall
}

func newWebClient(opts *options, headers []headerPair, ss *statusSet) *webClient {
	c := &webClient{
		opts:      opts,
		headers:   headers,
		statusSet: ss,
		globalSem: make(chan struct{}, opts.MaxConnections),
		hostSems:  map[string]chan struct{}{},
		dnsCache:  map[string]*dnsCall{},
	}
	if opts.DNSResolver != "" {
		addr := opts.DNSResolver
		c.resolver = &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context.Context, network, _ string) (net.Conn, error) {
				var d net.Dialer
				return d.DialContext(ctx, network, addr)
			},
		}
	} else {
		c.resolver = net.DefaultResolver
	}
	return c
}

func (c *webClient) hostSemaphore(u *url.URL) chan struct{} {
	key := strings.ToLower(u.Host)
	c.hostMu.Lock()
	defer c.hostMu.Unlock()
	sem, ok := c.hostSems[key]
	if !ok {
		sem = make(chan struct{}, c.opts.MaxConnectionsPerHost)
		c.hostSems[key] = sem
	}
	return sem
}

func (c *webClient) waitRate() {
	if c.opts.RateLimit <= 0 {
		return
	}
	interval := time.Second / time.Duration(c.opts.RateLimit)
	c.rateMu.Lock()
	now := time.Now()
	slot := c.rateNext
	if slot.Before(now) {
		slot = now
	}
	c.rateNext = slot.Add(interval)
	c.rateMu.Unlock()
	if wait := time.Until(slot); wait > 0 {
		time.Sleep(wait)
	}
}

// getChecked performs redirects and then checks the final status code.
func (c *webClient) getChecked(u *url.URL) (*rawResponse, error) {
	resp, err := c.getRedirect(u, 0)
	if err != nil {
		return nil, err
	}
	if !c.statusSet.contains(resp.status) {
		return nil, errors.New(strconv.Itoa(resp.status))
	}
	decoded, err := decodeResponseBody(resp)
	if err != nil {
		return nil, err
	}
	resp.body = decoded
	return resp, nil
}

func decodeResponseBody(resp *rawResponse) ([]byte, error) {
	enc := strings.TrimSpace(resp.headerLast("Content-Encoding"))
	switch enc {
	case "gzip":
		r, err := gzip.NewReader(bytes.NewReader(resp.body))
		if err != nil {
			return nil, err
		}
		defer r.Close()
		return io.ReadAll(r)
	case "deflate":
		r, err := zlib.NewReader(bytes.NewReader(resp.body))
		if err != nil {
			return nil, err
		}
		defer r.Close()
		return io.ReadAll(r)
	case "br":
		return decodeBrotli(resp.body)
	}
	return resp.body, nil
}

func (c *webClient) getRedirect(u *url.URL, count int) (*rawResponse, error) {
	if count > c.opts.MaxRedirections {
		return nil, errors.New("too many redirections")
	}
	resp, err := c.getRetry(u)
	if err != nil {
		return nil, err
	}
	if resp.status < 300 || resp.status >= 400 {
		return resp, nil
	}
	loc := resp.headerFirst("Location")
	if loc == "" {
		return nil, errors.New("location header not set")
	}
	next, err := u.Parse(loc)
	if err != nil {
		return nil, err
	}
	next.Fragment = ""
	next.RawFragment = ""
	resp2, err := c.getRedirect(next, count+1)
	if err != nil {
		// Errors from a further redirect step are already shaped; an error
		// produced while fetching the immediate target gets annotated.
		// getRedirect marks errors raised by its own level via the
		// redirectError wrapper, so only annotate unmarked ones once.
		var re *redirectError
		if errors.As(err, &re) {
			return nil, re.err
		}
		return nil, &redirectError{err: fmt.Errorf("%v (following redirect %s)", err, next.String())}
	}
	return resp2, nil
}

type redirectError struct{ err error }

func (e *redirectError) Error() string { return e.err.Error() }
func (e *redirectError) Unwrap() error { return e.err }

func isNetTimeout(err error) bool {
	var ne net.Error
	return errors.As(err, &ne) && ne.Timeout()
}

func (c *webClient) getRetry(u *url.URL) (*rawResponse, error) {
	var retries uint64
	backoff := 500 * time.Millisecond
	for {
		resp, err := c.getThrottled(u)
		if err == nil {
			return resp, nil
		}
		if !isNetTimeout(err) {
			return nil, err
		}
		time.Sleep(backoff)
		backoff *= 2
		if retries >= c.opts.MaxRetries {
			if c.opts.MaxRetries > 0 {
				return nil, fmt.Errorf("max retry count %d exceeded: %w", c.opts.MaxRetries, err)
			}
			return nil, err
		}
		retries++
	}
}

func (c *webClient) getThrottled(u *url.URL) (*rawResponse, error) {
	c.globalSem <- struct{}{}
	defer func() { <-c.globalSem }()
	hs := c.hostSemaphore(u)
	hs <- struct{}{}
	defer func() { <-hs }()
	c.waitRate()
	return c.doRaw(u)
}

func (c *webClient) doRaw(u *url.URL) (*rawResponse, error) {
	var lastErr error
	for attempt := 0; attempt < 5; attempt++ {
		resp, err := c.doOne(u)
		if err == nil {
			return resp, nil
		}
		if errors.Is(err, errTimeout) || errors.Is(err, errBodyTooLarge) {
			return nil, err
		}
		var ire *internalRetryError
		if !errors.As(err, &ire) {
			return nil, err
		}
		lastErr = ire.err
	}
	return nil, lastErr
}

func fastHTTPURLString(u *url.URL) string {
	scheme := strings.ToLower(u.Scheme)
	if scheme == "" {
		scheme = "http"
	}
	var b strings.Builder
	b.WriteString(scheme)
	b.WriteString("://")
	b.WriteString(strings.ToLower(u.Host))
	path := u.EscapedPath()
	if path == "" && u.RawQuery == "" && !u.ForceQuery {
		path = "/"
	}
	b.WriteString(path)
	if u.RawQuery != "" {
		b.WriteString("?")
		b.WriteString(u.RawQuery)
	}
	return b.String()
}

func requestURI(u *url.URL) string {
	path := u.EscapedPath()
	if path == "" {
		if u.RawQuery == "" {
			return "/"
		}
		return "?" + u.RawQuery
	}
	if u.RawQuery != "" {
		return path + "?" + u.RawQuery
	}
	return path
}

func (c *webClient) resolveHost(hostname string) ([]net.IP, error) {
	if ip := net.ParseIP(hostname); ip != nil {
		return []net.IP{ip}, nil
	}
	c.dnsMu.Lock()
	call, ok := c.dnsCache[hostname]
	if !ok {
		call = &dnsCall{done: make(chan struct{})}
		c.dnsCache[hostname] = call
		go func() {
			addrs, err := c.resolver.LookupIPAddr(context.Background(), hostname)
			if err != nil {
				call.err = err
				// Do not cache failures permanently; drop the entry after
				// waking waiters by deleting before close under lock below.
			} else {
				for _, a := range addrs {
					call.ips = append(call.ips, a.IP)
				}
				if len(call.ips) == 0 {
					call.err = &net.DNSError{Err: "no such host", Name: hostname, IsNotFound: true}
				}
			}
			if call.err != nil {
				c.dnsMu.Lock()
				if c.dnsCache[hostname] == call {
					delete(c.dnsCache, hostname)
				}
				c.dnsMu.Unlock()
			}
			close(call.done)
		}()
	}
	c.dnsMu.Unlock()
	<-call.done
	return call.ips, call.err
}

// dialTargetAddr returns the host:port to dial for u, applying the scheme
// default port, or an error mirroring the reference client.
func dialInfo(u *url.URL) (scheme, hostname, portStr string, err error) {
	scheme = strings.ToLower(u.Scheme)
	if scheme == "" {
		scheme = "http"
	}
	if scheme != "http" && scheme != "https" {
		return "", "", "", fmt.Errorf("unsupported protocol %q. http and https are supported", u.Scheme)
	}
	if u.Host == "" {
		return "", "", "", errors.New("missing port in address")
	}
	defPort := "80"
	if scheme == "https" {
		defPort = "443"
	}
	hostname = u.Hostname()
	portStr = u.Port()
	if hostname == "" && portStr != "" {
		// e.g. host ":80": reference client appends the default port and
		// then fails to split the result.
		bad := u.Host + ":" + defPort
		_, _, serr := net.SplitHostPort(bad)
		if serr != nil {
			return "", "", "", serr
		}
	}
	if portStr == "" {
		portStr = defPort
	}
	return scheme, hostname, portStr, nil
}

func (c *webClient) dialDirect(ctx context.Context, hostname, portStr string) (net.Conn, error) {
	ips, err := c.resolveHost(hostname)
	if err != nil {
		return nil, err
	}
	port, _ := strconv.Atoi(portStr)
	var firstErr error
	var d net.Dialer
	for _, ip := range ips {
		addr := &net.TCPAddr{IP: ip, Port: port}
		conn, derr := d.DialContext(ctx, "tcp", addr.String())
		if derr == nil {
			return conn, nil
		}
		if firstErr == nil {
			firstErr = fmt.Errorf("error when dialing %s: %w", addr.String(), derr)
		}
		if ctx.Err() != nil {
			break
		}
	}
	if firstErr == nil {
		firstErr = errors.New("missing port in address")
	}
	return nil, firstErr
}

func (c *webClient) dialProxy(ctx context.Context, targetAddr string) (net.Conn, *bufio.Reader, error) {
	proxy := c.opts.Proxy
	if strings.HasPrefix(proxy, "https://") {
		// Observed: an https:// proxy value is ignored (direct connection
		// is used instead). This is signalled to the caller by a sentinel.
		return nil, nil, errNoProxy
	}
	addr := strings.TrimPrefix(proxy, "http://")
	auth := ""
	if at := strings.LastIndex(addr, "@"); at >= 0 {
		auth = addr[:at]
		addr = addr[at+1:]
	}
	idx := strings.LastIndex(addr, ":")
	if idx < 0 {
		return nil, nil, fmt.Errorf("address %s: missing port in address", addr)
	}
	if _, err := strconv.Atoi(addr[idx+1:]); err != nil {
		return nil, nil, err
	}
	var d net.Dialer
	conn, err := d.DialContext(ctx, "tcp4", addr)
	if err != nil {
		return nil, nil, fmt.Errorf("error when dialing %s: %w", addr, err)
	}
	// Send CONNECT.
	var req strings.Builder
	req.WriteString("CONNECT " + targetAddr + " HTTP/1.1\r\n")
	req.WriteString("Host: " + targetAddr + "\r\n")
	if auth != "" {
		req.WriteString("Proxy-Authorization: Basic " + base64.StdEncoding.EncodeToString([]byte(auth)) + "\r\n")
	}
	req.WriteString("\r\n")
	if _, err := io.WriteString(conn, req.String()); err != nil {
		conn.Close()
		return nil, nil, err
	}
	br := bufio.NewReaderSize(conn, c.effectiveBufferSize())
	head, err := readHeaderBlock(br, true)
	if err != nil {
		conn.Close()
		return nil, nil, unwrapHeaderErr(err)
	}
	status, _, perr := parseResponseHead(head.data, head.peek)
	if perr != nil {
		conn.Close()
		return nil, nil, perr
	}
	if status != 200 {
		conn.Close()
		return nil, nil, fmt.Errorf("could not connect to proxyAddr: %s status code: %d", addr, status)
	}
	return conn, br, nil
}

var errNoProxy = errors.New("__no_proxy__")

func unwrapHeaderErr(err error) error {
	var ire *internalRetryError
	if errors.As(err, &ire) {
		return ire.err
	}
	return err
}

func (c *webClient) effectiveBufferSize() int {
	if c.opts.BufferSize <= 0 {
		return 4096
	}
	if c.opts.BufferSize < 16 {
		return 16
	}
	return c.opts.BufferSize
}

func (c *webClient) doOne(u *url.URL) (*rawResponse, error) {
	if c.opts.Timeout <= 0 {
		return nil, errTimeout
	}
	deadline := time.Now().Add(time.Duration(c.opts.Timeout) * time.Second)
	ctx, cancel := context.WithDeadline(context.Background(), deadline)
	defer cancel()

	scheme, hostname, portStr, err := dialInfo(u)
	if err != nil {
		return nil, err
	}
	targetAddr := net.JoinHostPort(hostname, portStr)

	var conn net.Conn
	var br *bufio.Reader
	if c.opts.Proxy != "" {
		pconn, pbr, perr := c.dialProxy(ctx, targetAddr)
		if perr == errNoProxy {
			conn, err = c.dialDirect(ctx, hostname, portStr)
			if err != nil {
				return nil, mapDialErr(err, ctx)
			}
		} else if perr != nil {
			return nil, mapDialErr(perr, ctx)
		} else {
			conn = pconn
			br = pbr
		}
	} else {
		conn, err = c.dialDirect(ctx, hostname, portStr)
		if err != nil {
			return nil, mapDialErr(err, ctx)
		}
	}
	defer conn.Close()
	conn.SetDeadline(deadline)

	if scheme == "https" {
		tlsConfig := &tls.Config{
			InsecureSkipVerify: c.opts.SkipTLS,
			ServerName:         hostname,
		}
		tconn := tls.Client(conn, tlsConfig)
		if herr := tconn.HandshakeContext(ctx); herr != nil {
			if ctx.Err() != nil {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: herr}
		}
		conn = tconn
		// Any bytes buffered by br belong to the proxy CONNECT exchange and
		// must be fed into TLS; in practice the proxy response consumed
		// exactly its headers, and a buffered reader here would only hold
		// tunnel bytes the proxy already forwarded (none yet).
		br = bufio.NewReaderSize(conn, c.effectiveBufferSize())
	} else if br == nil {
		br = bufio.NewReaderSize(conn, c.effectiveBufferSize())
	}

	// Write the request.
	req := c.buildRequest(u, scheme)
	if _, err := io.WriteString(conn, req); err != nil {
		if ctx.Err() != nil {
			return nil, errTimeout
		}
		return nil, &internalRetryError{err: err}
	}
	resp, err := readResponse(br, c)
	if err != nil {
		if errors.Is(err, errTimeout) || errors.Is(err, errBodyTooLarge) {
			return nil, err
		}
		if ctx.Err() != nil {
			return nil, errTimeout
		}
		return nil, err
	}
	resp.finalURL = fastHTTPURLString(u)
	return resp, nil
}

func mapDialErr(err error, ctx context.Context) error {
	if ctx.Err() != nil && isNetTimeout(err) {
		return errTimeout
	}
	return err
}

func canonicalHeaderKey(k string) string {
	// Validate as an HTTP token; if invalid, return as-is.
	for i := 0; i < len(k); i++ {
		c := k[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("!#$%&'*+-.^_`|~", rune(c))) {
			return k
		}
	}
	var b strings.Builder
	upper := true
	for i := 0; i < len(k); i++ {
		ch := k[i]
		if upper && ch >= 'a' && ch <= 'z' {
			ch -= 32
		} else if !upper && ch >= 'A' && ch <= 'Z' {
			ch += 32
		}
		b.WriteByte(ch)
		upper = ch == '-'
	}
	return b.String()
}

func (c *webClient) buildRequest(u *url.URL, scheme string) string {
	var b strings.Builder
	b.WriteString("GET ")
	b.WriteString(requestURI(u))
	b.WriteString(" HTTP/1.1\r\n")

	// Gather headers. Special single-value headers get fixed positions,
	// everything else is written in the order supplied.
	userAgent := ""
	accept := "*/*"
	connection := "close"
	type kv = headerPair
	var generic []kv
	haveUA, haveAccept, haveConn := false, false, false
	for _, h := range c.headers {
		ck := canonicalHeaderKey(h.key)
		switch strings.ToLower(ck) {
		case "host":
			// Ignored; the real host wins.
		case "user-agent":
			if !haveUA {
				userAgent = h.value
				haveUA = true
			} else {
				generic = append(generic, kv{ck, h.value})
			}
		case "accept":
			if !haveAccept {
				accept = h.value
				haveAccept = true
			} else {
				generic = append(generic, kv{ck, h.value})
			}
		case "connection":
			if !haveConn {
				connection = h.value
				haveConn = true
			} else {
				generic = append(generic, kv{ck, h.value})
			}
		default:
			generic = append(generic, kv{ck, h.value})
		}
	}
	// Userinfo authorization overrides any custom Authorization headers.
	auth := ""
	if u.User != nil && u.User.Username() != "" {
		pw, _ := u.User.Password()
		auth = "Basic " + base64.StdEncoding.EncodeToString([]byte(u.User.Username()+":"+pw))
		// Remove custom Authorization entries.
		filtered := generic[:0]
		// Note: reuse of the backing array is fine because we only shrink.
		out := make([]kv, 0, len(generic))
		for _, g := range generic {
			if strings.EqualFold(g.key, "Authorization") {
				continue
			}
			out = append(out, g)
		}
		_ = filtered
		generic = out
	}

	if haveUA {
		b.WriteString("User-Agent: " + userAgent + "\r\n")
	}
	host := strings.ToLower(u.Host)
	b.WriteString("Host: " + host + "\r\n")
	cookieHeaders := []kv{}
	for _, g := range generic {
		if strings.EqualFold(g.key, "Cookie") {
			cookieHeaders = append(cookieHeaders, g)
			continue
		}
		b.WriteString(g.key + ": " + g.value + "\r\n")
	}
	b.WriteString("Accept: " + accept + "\r\n")
	for _, g := range cookieHeaders {
		b.WriteString(g.key + ": " + g.value + "\r\n")
	}
	if auth != "" {
		b.WriteString("Authorization: " + auth + "\r\n")
	}
	b.WriteString("Connection: " + connection + "\r\n")
	b.WriteString("\r\n")
	return b.String()
}

// ---- Response parsing ----

type headerBlock struct {
	data []byte // the consumed header bytes
	peek []byte // bytes that were buffered when the header end was found
}

func findHeaderEnd(data []byte) (int, bool) {
	best := -1
	if i := bytes.Index(data, []byte("\r\n\r\n")); i >= 0 {
		best = i + 4
	}
	if i := bytes.Index(data, []byte("\n\n")); i >= 0 && (best < 0 || i+2 < best) {
		best = i + 2
	}
	if i := bytes.Index(data, []byte("\r\n\n")); i >= 0 && (best < 0 || i+3 < best) {
		best = i + 3
	}
	if i := bytes.Index(data, []byte("\n\r\n")); i >= 0 && (best < 0 || i+3 < best) {
		best = i + 3
	}
	return best, best >= 0
}

func readHeaderBlock(br *bufio.Reader, first bool) (*headerBlock, error) {
	size := br.Size()
	for {
		data, err := br.Peek(size)
		if len(data) == 0 && err == io.EOF {
			if first {
				return nil, &internalRetryError{err: errServerClosed}
			}
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: EOF. Buffer size=0, contents: %q", "")}
		}
		if end, ok := findHeaderEnd(data); ok {
			peekCopy := append([]byte(nil), data...)
			consumed, _ := br.Discard(end)
			return &headerBlock{data: peekCopy[:consumed], peek: peekCopy}, nil
		}
		if len(data) >= size {
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: small read buffer. Increase ReadBufferSize. Buffer size=%d, contents: %q", len(data), string(data))}
		}
		if err == io.EOF {
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: EOF. Buffer size=%d, contents: %q", len(data), string(data))}
		}
		if err != nil && err != bufio.ErrBufferFull {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: %v. Buffer size=%d, contents: %q", err, len(data), string(data))}
		}
		// Need more bytes: force another fill.
		_, perr := br.Peek(len(data) + 1)
		if perr != nil && perr != bufio.ErrBufferFull && perr != io.EOF {
			if isNetTimeout(perr) {
				return nil, errTimeout
			}
		}
		if perr == io.EOF {
			continue
		}
	}
}

func parseResponseHead(data, peek []byte) (int, []headerPair, error) {
	text := strings.ReplaceAll(string(data), "\r\n", "\n")
	lines := strings.Split(text, "\n")
	firstLine := ""
	if len(lines) > 0 {
		firstLine = lines[0]
	}
	wsIdx := strings.IndexAny(firstLine, " \t")
	if wsIdx < 0 {
		return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: cannot find whitespace in the first line of response %q. Buffer size=%d, contents: %q", string(peek), len(peek), string(peek))}
	}
	rest := strings.TrimLeft(firstLine[wsIdx:], " \t")
	statusStr := rest
	if i := strings.IndexAny(rest, " \t"); i >= 0 {
		statusStr = rest[:i]
	}
	status, serr := strconv.Atoi(statusStr)
	if serr != nil {
		return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: cannot parse response status code %q. Buffer size=%d, contents: %q", statusStr, len(peek), string(peek))}
	}
	var headers []headerPair
	for _, line := range lines[1:] {
		if line == "" {
			continue
		}
		if line[0] == ' ' || line[0] == '\t' {
			// Continuation of the previous header.
			if len(headers) > 0 {
				headers[len(headers)-1].value += " " + strings.Trim(line, " \t")
			}
			continue
		}
		colon := strings.Index(line, ":")
		if colon < 0 {
			continue
		}
		key := strings.Trim(line[:colon], " \t")
		value := strings.Trim(line[colon+1:], " \t")
		headers = append(headers, headerPair{key: key, value: value})
	}
	return status, headers, nil
}

func readResponse(br *bufio.Reader, c *webClient) (*rawResponse, error) {
	var status int
	var headers []headerPair
	first := true
	for {
		head, err := readHeaderBlock(br, first)
		if err != nil {
			return nil, err
		}
		s, h, perr := parseResponseHead(head.data, head.peek)
		if perr != nil {
			return nil, perr
		}
		first = false
		if s == 100 {
			continue
		}
		status, headers = s, h
		break
	}
	resp := &rawResponse{status: status, headers: headers}
	body, err := readResponseBody(br, resp, c.opts.MaxResponseBodySize)
	if err != nil {
		return nil, err
	}
	resp.body = body
	return resp, nil
}

func readResponseBody(br *bufio.Reader, resp *rawResponse, maxBody int) ([]byte, error) {
	// Statuses that never carry a body.
	if resp.status == 204 || resp.status == 304 || resp.status >= 100 && resp.status < 200 && resp.status != 101 {
		// 101 is treated as a final response with the announced body.
		if resp.status != 101 {
			return []byte{}, nil
		}
	}
	te := strings.ToLower(strings.TrimSpace(resp.headerLast("Transfer-Encoding")))
	if te == "chunked" || strings.HasSuffix(te, ", chunked") || strings.Contains(te, "chunked") {
		return readChunkedBody(br, maxBody)
	}
	if cl := resp.headerLast("Content-Length"); cl != "" {
		n, err := strconv.ParseInt(strings.TrimSpace(cl), 10, 64)
		if err != nil {
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response body: %v", err)}
		}
		if n < 0 {
			return readUntilEOF(br, maxBody)
		}
		if maxBody > 0 && n > int64(maxBody) {
			return nil, errBodyTooLarge
		}
		buf := make([]byte, n)
		if _, err := io.ReadFull(br, buf); err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		return buf, nil
	}
	return readUntilEOF(br, maxBody)
}

func readUntilEOF(br *bufio.Reader, maxBody int) ([]byte, error) {
	var buf bytes.Buffer
	tmp := make([]byte, 32*1024)
	for {
		n, err := br.Read(tmp)
		if n > 0 {
			buf.Write(tmp[:n])
			if maxBody > 0 && buf.Len() > maxBody {
				return nil, errBodyTooLarge
			}
		}
		if err == io.EOF {
			return buf.Bytes(), nil
		}
		if err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: err}
		}
	}
}

func readChunkedBody(br *bufio.Reader, maxBody int) ([]byte, error) {
	var buf bytes.Buffer
	for {
		line, err := br.ReadString('\n')
		if err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		line = strings.TrimRight(line, "\r\n")
		sizeStr := line
		if i := strings.Index(sizeStr, ";"); i >= 0 {
			sizeStr = sizeStr[:i]
		}
		sizeStr = strings.TrimSpace(sizeStr)
		size, herr := parseHex(sizeStr)
		if herr != nil {
			return nil, &internalRetryError{err: herr}
		}
		if size == 0 {
			// Trailers until an empty line.
			for {
				tl, terr := br.ReadString('\n')
				if terr != nil {
					if isNetTimeout(terr) {
						return nil, errTimeout
					}
					return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
				}
				if tl == "\r\n" || tl == "\n" {
					break
				}
			}
			return buf.Bytes(), nil
		}
		if maxBody > 0 && buf.Len()+size > maxBody {
			return nil, errBodyTooLarge
		}
		if _, err := io.CopyN(&buf, br, int64(size)); err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		// Trailing CRLF.
		var crlf [2]byte
		if _, err := io.ReadFull(br, crlf[:]); err != nil {
			// Some servers omit the final CRLF on the last byte; accept a
			// single LF by peeking is complex, so treat a short read of a
			// lone '\n' as fine.
			if !(crlf[0] == '\n') {
				if isNetTimeout(err) {
					return nil, errTimeout
				}
				return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
			}
		}
	}
}

func parseHex(s string) (int, error) {
	if s == "" {
		return 0, errors.New("empty hex number")
	}
	v := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			if i == 0 {
