		// must be fed into TLS; in practice the proxy response consumed
		// exactly its headers, and a buffered reader here would only hold
		// tunnel bytes the proxy already forwarded (none yet).
		br = bufio.NewReaderSize(conn, c.effectiveBufferSize())
	} else if br == nil {
		br = bufio.NewReaderSize(conn, c.effectiveBufferSize())
	}

