func canonicalHeaderKey(k string) string {
	// Validate as an HTTP token; if invalid, return as-is.
	for i := 0; i < len(k); i++ {
		c := k[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("!#$%&'*+-.^_`|~", rune(c))) {
			return k
		}
	}
	var b strings.Builder
	upper := true
	for i := 0; i < len(k); i++ {
		ch := k[i]
		if upper && ch >= 'a' && ch <= 'z' {
			ch -= 32
		} else if !upper && ch >= 'A' && ch <= 'Z' {
			ch += 32
		}
		b.WriteByte(ch)
		upper = ch == '-'
	}
	return b.String()
}

func (c *webClient) buildRequest(u *url.URL, scheme string) string {
	var b strings.Builder
	b.WriteString("GET ")
	b.WriteString(requestURI(u))
	b.WriteString(" HTTP/1.1\r\n")

	// Gather headers. Special single-value headers get fixed positions,
	// everything else is written in the order supplied.
	userAgent := ""
	accept := "*/*"
	connection := "close"
	type kv = headerPair
	var generic []kv
	haveUA, haveAccept, haveConn := false, false, false
	for _, h := range c.headers {
		ck := canonicalHeaderKey(h.key)
		switch strings.ToLower(ck) {
		case "host":
			// Ignored; the real host wins.
		case "user-agent":
			if !haveUA {
				userAgent = h.value
				haveUA = true
			} else {
				generic = append(generic, kv{ck, h.value})
			}
		case "accept":
			if !haveAccept {
				accept = h.value
				haveAccept = true
			} else {
				generic = append(generic, kv{ck, h.value})
			}
		case "connection":
			if !haveConn {
				connection = h.value
				haveConn = true
			} else {
				generic = append(generic, kv{ck, h.value})
			}
		default:
			generic = append(generic, kv{ck, h.value})
		}
	}
	// Userinfo authorization overrides any custom Authorization headers.
	auth := ""
	if u.User != nil && u.User.Username() != "" {
		pw, _ := u.User.Password()
		auth = "Basic " + base64.StdEncoding.EncodeToString([]byte(u.User.Username()+":"+pw))
		// Remove custom Authorization entries.
		filtered := generic[:0]
		// Note: reuse of the backing array is fine because we only shrink.
		out := make([]kv, 0, len(generic))
		for _, g := range generic {
			if strings.EqualFold(g.key, "Authorization") {
				continue
			}
			out = append(out, g)
		}
		_ = filtered
		generic = out
	}

	if haveUA {
		b.WriteString("User-Agent: " + userAgent + "\r\n")
	}
	host := strings.ToLower(u.Host)
	b.WriteString("Host: " + host + "\r\n")
	cookieHeaders := []kv{}
	for _, g := range generic {
		if strings.EqualFold(g.key, "Cookie") {
			cookieHeaders = append(cookieHeaders, g)
			continue
		}
		b.WriteString(g.key + ": " + g.value + "\r\n")
	}
	b.WriteString("Accept: " + accept + "\r\n")
	for _, g := range cookieHeaders {
		b.WriteString(g.key + ": " + g.value + "\r\n")
	}
	if auth != "" {
		b.WriteString("Authorization: " + auth + "\r\n")
	}
	b.WriteString("Connection: " + connection + "\r\n")
	b.WriteString("\r\n")
	return b.String()
}

// ---- Response parsing ----

type headerBlock struct {
	data []byte // the consumed header bytes
	peek []byte // bytes that were buffered when the header end was found
}

func findHeaderEnd(data []byte) (int, bool) {
	best := -1
	if i := bytes.Index(data, []byte("\r\n\r\n")); i >= 0 {
		best = i + 4
	}
	if i := bytes.Index(data, []byte("\n\n")); i >= 0 && (best < 0 || i+2 < best) {
		best = i + 2
	}
	if i := bytes.Index(data, []byte("\r\n\n")); i >= 0 && (best < 0 || i+3 < best) {
		best = i + 3
	}
	if i := bytes.Index(data, []byte("\n\r\n")); i >= 0 && (best < 0 || i+3 < best) {
		best = i + 3
	}
	return best, best >= 0
}

func readHeaderBlock(br *bufio.Reader, first bool) (*headerBlock, error) {
	size := br.Size()
	for {
		data, err := br.Peek(size)
		if len(data) == 0 && err == io.EOF {
			if first {
				return nil, &internalRetryError{err: errServerClosed}
			}
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: EOF. Buffer size=0, contents: %q", "")}
		}
		if end, ok := findHeaderEnd(data); ok {
			peekCopy := append([]byte(nil), data...)
			consumed, _ := br.Discard(end)
			return &headerBlock{data: peekCopy[:consumed], peek: peekCopy}, nil
		}
		if len(data) >= size {
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: small read buffer. Increase ReadBufferSize. Buffer size=%d, contents: %q", len(data), string(data))}
		}
		if err == io.EOF {
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: EOF. Buffer size=%d, contents: %q", len(data), string(data))}
		}
		if err != nil && err != bufio.ErrBufferFull {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: %v. Buffer size=%d, contents: %q", err, len(data), string(data))}
		}
		// Need more bytes: force another fill.
		_, perr := br.Peek(len(data) + 1)
		if perr != nil && perr != bufio.ErrBufferFull && perr != io.EOF {
			if isNetTimeout(perr) {
				return nil, errTimeout
			}
		}
		if perr == io.EOF {
			continue
		}
	}
}

func parseResponseHead(data, peek []byte) (int, []headerPair, error) {
	text := strings.ReplaceAll(string(data), "\r\n", "\n")
	lines := strings.Split(text, "\n")
	firstLine := ""
	if len(lines) > 0 {
		firstLine = lines[0]
	}
	wsIdx := strings.IndexAny(firstLine, " \t")
	if wsIdx < 0 {
		return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: cannot find whitespace in the first line of response %q. Buffer size=%d, contents: %q", string(peek), len(peek), string(peek))}
	}
	rest := strings.TrimLeft(firstLine[wsIdx:], " \t")
	statusStr := rest
	if i := strings.IndexAny(rest, " \t"); i >= 0 {
		statusStr = rest[:i]
	}
	status, serr := strconv.Atoi(statusStr)
	if serr != nil {
		return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: cannot parse response status code %q. Buffer size=%d, contents: %q", statusStr, len(peek), string(peek))}
	}
	var headers []headerPair
	for _, line := range lines[1:] {
		if line == "" {
			continue
		}
		if line[0] == ' ' || line[0] == '\t' {
			// Continuation of the previous header.
			if len(headers) > 0 {
				headers[len(headers)-1].value += " " + strings.Trim(line, " \t")
			}
			continue
		}
		colon := strings.Index(line, ":")
		if colon < 0 {
			continue
		}
		key := strings.Trim(line[:colon], " \t")
		value := strings.Trim(line[colon+1:], " \t")
		headers = append(headers, headerPair{key: key, value: value})
	}
	return status, headers, nil
}

func readResponse(br *bufio.Reader, c *webClient) (*rawResponse, error) {
	var status int
	var headers []headerPair
	first := true
	for {
		head, err := readHeaderBlock(br, first)
		if err != nil {
			return nil, err
		}
		s, h, perr := parseResponseHead(head.data, head.peek)
		if perr != nil {
			return nil, perr
		}
		first = false
		if s == 100 {
			continue
		}
		status, headers = s, h
		break
	}
	resp := &rawResponse{status: status, headers: headers}
	body, err := readResponseBody(br, resp, c.opts.MaxResponseBodySize)
	if err != nil {
		return nil, err
	}
	resp.body = body
	return resp, nil
}

func readResponseBody(br *bufio.Reader, resp *rawResponse, maxBody int) ([]byte, error) {
	// Statuses that never carry a body.
	if resp.status == 204 || resp.status == 304 || resp.status >= 100 && resp.status < 200 && resp.status != 101 {
		// 101 is treated as a final response with the announced body.
		if resp.status != 101 {
			return []byte{}, nil
		}
	}
	te := strings.ToLower(strings.TrimSpace(resp.headerLast("Transfer-Encoding")))
	if te == "chunked" || strings.HasSuffix(te, ", chunked") || strings.Contains(te, "chunked") {
		return readChunkedBody(br, maxBody)
	}
	if cl := resp.headerLast("Content-Length"); cl != "" {
		n, err := strconv.ParseInt(strings.TrimSpace(cl), 10, 64)
		if err != nil {
			return nil, &internalRetryError{err: fmt.Errorf("error when reading response body: %v", err)}
		}
		if n < 0 {
			return readUntilEOF(br, maxBody)
		}
		if maxBody > 0 && n > int64(maxBody) {
			return nil, errBodyTooLarge
		}
		buf := make([]byte, n)
		if _, err := io.ReadFull(br, buf); err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		return buf, nil
	}
	return readUntilEOF(br, maxBody)
}

func readUntilEOF(br *bufio.Reader, maxBody int) ([]byte, error) {
	var buf bytes.Buffer
	tmp := make([]byte, 32*1024)
	for {
		n, err := br.Read(tmp)
		if n > 0 {
			buf.Write(tmp[:n])
			if maxBody > 0 && buf.Len() > maxBody {
				return nil, errBodyTooLarge
			}
		}
		if err == io.EOF {
			return buf.Bytes(), nil
		}
		if err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: err}
		}
	}
}

func readChunkedBody(br *bufio.Reader, maxBody int) ([]byte, error) {
	var buf bytes.Buffer
	for {
		line, err := br.ReadString('\n')
		if err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		line = strings.TrimRight(line, "\r\n")
		sizeStr := line
		if i := strings.Index(sizeStr, ";"); i >= 0 {
			sizeStr = sizeStr[:i]
		}
		sizeStr = strings.TrimSpace(sizeStr)
		size, herr := parseHex(sizeStr)
		if herr != nil {
			return nil, &internalRetryError{err: herr}
		}
		if size == 0 {
			// Trailers until an empty line.
			for {
				tl, terr := br.ReadString('\n')
				if terr != nil {
					if isNetTimeout(terr) {
						return nil, errTimeout
					}
					return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
				}
				if tl == "\r\n" || tl == "\n" {
					break
				}
			}
			return buf.Bytes(), nil
		}
		if maxBody > 0 && buf.Len()+size > maxBody {
			return nil, errBodyTooLarge
		}
		if _, err := io.CopyN(&buf, br, int64(size)); err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		// Trailing CRLF.
		var crlf [2]byte
		if _, err := io.ReadFull(br, crlf[:]); err != nil {
			// Some servers omit the final CRLF on the last byte; accept a
			// single LF by peeking is complex, so treat a short read of a
			// lone '\n' as fine.
			if !(crlf[0] == '\n') {
				if isNetTimeout(err) {
					return nil, errTimeout
				}
				return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
			}
		}
	}
}

func parseHex(s string) (int, error) {
	if s == "" {
		return 0, errors.New("empty hex number")
	}
	v := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			if i == 0 {
				return 0, errors.New("empty hex number")
			}
			return 0, fmt.Errorf("invalid character %q in hex number", c)
		}
		v = v*16 + d
	}
	return v, nil
}
