{"command":"cat <<'EOF' > checker.go
package main

import (
	"errors"
	"fmt"
	"mime"
	"net/url"
	"os"
	"strings"
	"sync"
)

type targetData struct {
	status   int
	finalURL string
	page     *pageData
}

type cachedResult struct {
	status   int
	finalURL string
	page     *pageData
	err      error
}

type fetchCall struct {
	done   chan struct{}
	result cachedResult
}

type linkFetcher struct {
	client          *webClient
	filter          *linkFilter
	ignoreFragments bool

	mu    sync.Mutex
	calls map[string]*fetchCall
}

func newLinkFetcher(client *webClient, filter *linkFilter, ignoreFragments bool) *linkFetcher {
	return &linkFetcher{client: client, filter: filter, ignoreFragments: ignoreFragments, calls: map[string]*fetchCall{}}
}

func (f *linkFetcher) fetchString(s string) (*targetData, error) {
	u, err := url.Parse(s)
	if err != nil {
		return nil, err
	}
	return f.fetchURL(u)
}

func (f *linkFetcher) fetchURL(u *url.URL) (*targetData, error) {
	key := *u
	key.Fragment = ""
	key.RawFragment = ""
	res := f.sendWithCache(&key)
	if res.err != nil {
		return nil, res.err
	}
	if res.page != nil && !f.ignoreFragments && u.Fragment != "" {
		if !res.page.ids[u.Fragment] {
			return nil, fmt.Errorf("id #%s not found", u.Fragment)
		}
	}
	return &targetData{status: res.status, finalURL: res.finalURL, page: res.page}, nil
}

func (f *linkFetcher) sendWithCache(key *url.URL) cachedResult {
	ks := key.String()
	f.mu.Lock()
	call, ok := f.calls[ks]
	if !ok {
		call = &fetchCall{done: make(chan struct{})}
		f.calls[ks] = call
		f.mu.Unlock()
		call.result = f.sendRequest(key)
		close(call.done)
		return call.result
	}
	f.mu.Unlock()
	<-call.done
	return call.result
}

func (f *linkFetcher) sendRequest(key *url.URL) cachedResult {
	resp, err := f.client.getChecked(key)
	if err != nil {
		return cachedResult{err: err}
	}
	mt, _, err := mime.ParseMediaType(resp.contentType())
	if err != nil {
		return cachedResult{err: err}
	}
	var page *pageData
	switch mt {
	case "text/html":
		p, perr := parseHTMLPage(resp.body, resp.finalURL, f.filter)
		if perr != nil {
			return cachedResult{err: perr}
		}
		page = p
	case "text/xml", "application/xml":
		page = parseSitemapPage(resp.body, f.filter)
	}
	return cachedResult{status: resp.status, finalURL: resp.finalURL, page: page}
}

// ---- Crawling ----

type linkResult struct {
	url    string
	status int
	err    error
	target *targetData
}

type pageResult struct {
	url   string
	links []linkResult
}

type crawler struct {
	opts       *options
	fetcher    *linkFetcher
	robots     *robotsRules
	sitemapSet map[string]bool
	rootHost   string

	results chan pageResult
	wg      sync.WaitGroup

	mu      sync.Mutex
	visited map[string]bool
}

func (c *crawler) schedule(finalURL string, page *pageData) {
	c.mu.Lock()
	if c.visited[finalURL] {
		c.mu.Unlock()
		return
	}
	c.visited[finalURL] = true
	c.mu.Unlock()
	c.wg.Add(1)
	go func() {
		defer c.wg.Done()
		c.process(finalURL, page)
	}()
}

func (c *crawler) maybeSchedule(t *targetData) {
	if c.opts.OnePageOnly || t == nil || t.page == nil {
		return
	}
	c.mu.Lock()
	seen := c.visited[t.finalURL]
	c.mu.Unlock()
	if seen {
		return
	}
	parsed, err := url.Parse(t.finalURL)
	if err != nil {
		return
	}
	if !strings.EqualFold(parsed.Hostname(), c.rootHost) {
		return
	}
	if c.robots != nil && !c.robots.isAllowed(parsed.Path) {
		return
	}
	if c.opts.FollowSitemap && !c.sitemapSet[t.finalURL] {
		return
	}
	c.schedule(t.finalURL, t.page)
}

func (c *crawler) process(pageURL string, page *pageData) {
	ch := make(chan linkResult, len(page.links))
	for _, cand := range page.links {
		if cand.err != nil {
			ch <- linkResult{url: cand.raw, err: cand.err}
			continue
		}
		go func(cand linkCandidate) {
			target, err := c.fetcher.fetchURL(cand.url)
			if err != nil {
				ch <- linkResult{url: cand.url.String(), err: err}
				return
			}
			ch <- linkResult{url: cand.url.String(), status: target.status, target: target}
		}(cand)
	}
	collected := make([]linkResult, 0, len(page.links))
	for i := 0; i < len(page.links); i++ {
		r := <-ch
		collected = append(collected, r)
		if r.target != nil {
			c.maybeSchedule(r.target)
		}
	}
	// Stable partition: successful results first, then failures.
	links := make([]linkResult, 0, len(collected))
	for _, r := range collected {
		if r.err == nil {
			links = append(links, r)
		}
	}
	for _, r := range collected {
		if r.err != nil {
			links = append(links, r)
		}
	}
	c.results <- pageResult{url: pageURL, links: links}
}

func runChecker(opts *options, rootArg string) (int, error) {
	exclude, err := compilePatterns(opts.Exclude)
	if err != nil {
		return 1, err
	}
	include, err := compilePatterns(opts.Include)
	if err != nil {
		return 1, err
	}
	filter := &linkFilter{exclude: exclude, include: include}
	headers, err := parseHeaders(opts.Headers)
	if err != nil {
		return 1, err
	}
	statusSet, err := parseStatusSet(opts.AcceptedStatusCodes)
	if err != nil {
		return 1, err
	}
	kind, verbose, err := selectOutput(opts)
	if err != nil {
		return 1, err
	}
	client := newWebClient(opts, headers, statusSet)
	fetcher := newLinkFetcher(client, filter, opts.IgnoreFragments)

	rootTarget, err := fetcher.fetchString(rootArg)
	if err != nil {
		return 1, fmt.Errorf("failed to fetch root page: %w", err)
	}
	if rootTarget.page == nil {
		return 1, errors.New("root page has invalid content type")
	}
	rootFinalURL, err := url.Parse(rootTarget.finalURL)
	if err != nil {
		return 1, err
	}

	var robots *robotsRules
	if opts.FollowRobots {
		robotsURL := *rootFinalURL
		robotsURL.Path = "/robots.txt"
		robotsURL.RawPath = ""
		resp, rerr := client.getChecked(&robotsURL)
		if rerr != nil {
			return 1, fmt.Errorf("failed to fetch robots.txt: %w", rerr)
		}
		parsed, perr := parseRobots(resp.body)
		if perr != nil {
			return 1, perr
		}
		robots = parsed
	}
	var sitemapSet map[string]bool
	if opts.FollowSitemap {
		sitemapURL := *rootFinalURL
		sitemapURL.Path = "/sitemap.xml"
		sitemapURL.RawPath = ""
		resp, serr := client.getChecked(&sitemapURL)
		if serr != nil {
			return 1, fmt.Errorf("failed to GET sitemap.xml: %w", serr)
		}
		set, perr := parseSitemapAllowlist(resp.body)
		if perr != nil {
			return 1, fmt.Errorf("failed to parse sitemap.xml: %w", perr)
		}
		sitemapSet = set
	}

	c := &crawler{
		opts:       opts,
		fetcher:    fetcher,
		robots:     robots,
		sitemapSet: sitemapSet,
		rootHost:   rootFinalURL.Hostname(),
		results:    make(chan pageResult),
		visited:    map[string]bool{},
	}
	c.schedule(rootTarget.finalURL, rootTarget.page)
	go func() {
		c.wg.Wait()
		close(c.results)
	}()

	anyError := false
	mark := func(res pageResult) {
		for _, l := range res.links {
			if l.err != nil {
				anyError = true
			}
		}
	}

	switch kind {
	case outText:
		useColor := colorEnabled(opts.Color, os.Stdout)
		for res := range c.results {
			mark(res)
			printTextResult(os.Stdout, res, verbose, useColor)
		}
	case outJSON:
		var all []pageResult
		for res := range c.results {
			mark(res)
			all = append(all, res)
		}
		printJSONResults(os.Stdout, all, verbose)
	case outJUnit:
		var all []pageResult
		for res := range c.results {
			mark(res)
			all = append(all, res)
		}
		printJUnitResults(os.Stdout, all)
	}
	if anyError {
		return 1, nil
	}
	return 0, nil
}
