}

func newLinkFetcher(client *webClient, filter *linkFilter, ignoreFragments bool) *linkFetcher {
	return &linkFetcher{client: client, filter: filter, ignoreFragments: ignoreFragments, calls: map[string]*fetchCall{}}
}

func (f *linkFetcher) fetchString(s string) (*targetData, error) {
	u, err := url.Parse(s)
	if err != nil {
		return nil, err
	}
	return f.fetchURL(u)
}

func (f *linkFetcher) fetchURL(u *url.URL) (*targetData, error) {
	key := *u
	key.Fragment = ""
	key.RawFragment = ""
	res := f.sendWithCache(&key)
	if res.err != nil {
		return nil, res.err
	}
	if res.page != nil && !f.ignoreFragments && u.Fragment != "" {
		if !res.page.ids[u.Fragment] {
			return nil, fmt.Errorf("id #%s not found", u.Fragment)
		}
	}
	return &targetData{status: res.status, finalURL: res.finalURL, page: res.page}, nil
}

func (f *linkFetcher) sendWithCache(key *url.URL) cachedResult {
	ks := key.String()
	f.mu.Lock()
	call, ok := f.calls[ks]
	if !ok {
		call = &fetchCall{done: make(chan struct{})}
		f.calls[ks] = call
		f.mu.Unlock()
		call.result = f.sendRequest(key)
		close(call.done)
		return call.result
	}
	f.mu.Unlock()
	<-call.done
	return call.result
}

func (f *linkFetcher) sendRequest(key *url.URL) cachedResult {
	resp, err := f.client.getChecked(key)
	if err != nil {
		return cachedResult{err: err}
	}
	mt, _, err := mime.ParseMediaType(resp.contentType())
	if err != nil {
		return cachedResult{err: err}
	}
	var page *pageData
	switch mt {
	case "text/html":
		p, perr := parseHTMLPage(resp.body, resp.finalURL, f.filter)
		if perr != nil {
			return cachedResult{err: perr}
		}
		page = p
	case "text/xml", "application/xml":
		page = parseSitemapPage(resp.body, f.filter)
	}
	return cachedResult{status: resp.status, finalURL: resp.finalURL, page: page}
}

// ---- Crawling ----

type linkResult struct {
	url    string
	status int
	err    error
	target *targetData
}

type pageResult struct {
	url   string
	links []linkResult
}

type crawler struct {
	opts       *options
	fetcher    *linkFetcher
	robots     *robotsRules
	sitemapSet map[string]bool
	rootHost   string

	results chan pageResult
	wg      sync.WaitGroup

	mu      sync.Mutex
	visited map[string]bool
}

func (c *crawler) schedule(finalURL string, page *pageData) {
	c.mu.Lock()
	if c.visited[finalURL] {
		c.mu.Unlock()
		return
	}
	c.visited[finalURL] = true
	c.mu.Unlock()
	c.wg.Add(1)
	go func() {
		defer c.wg.Done()
		c.process(finalURL, page)
	}()
}

func (c *crawler) maybeSchedule(t *targetData) {
	if c.opts.OnePageOnly || t == nil || t.page == nil {
		return
	}
	c.mu.Lock()
	seen := c.visited[t.finalURL]
