		}
	}
	for _, r := range collected {
		if r.err != nil {
			links = append(links, r)
		}
	}
	c.results <- pageResult{url: pageURL, links: links}
}

func runChecker(opts *options, rootArg string) (int, error) {
	exclude, err := compilePatterns(opts.Exclude)
	if err != nil {
		return 1, err
	}
	include, err := compilePatterns(opts.Include)
	if err != nil {
		return 1, err
	}
