cat <<'EOF' > printer.go
package main

import (
	"encoding/json"
	"encoding/xml"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"syscall"
	"unsafe"
)

func colorEnabled(mode string, f *os.File) bool {
	switch mode {
	case "always":
		return true
	case "never":
		return false
	default:
		return isTerminal(f)
	}
}

func isTerminal(f *os.File) bool {
	const tcgets = 0x5401
	var buf [128]byte
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, f.Fd(), tcgets, uintptr(unsafe.Pointer(&buf[0])), 0, 0, 0)
	return errno == 0
}

func wrapColor(code string, s string, enabled bool) string {
	if !enabled {
		return s
	}
	return "\x1b[" + code + "m" + s + "\x1b[0m"
}

func resultString(l linkResult) string {
	if l.err != nil {
		return l.err.Error()
	}
	return strconv.Itoa(l.status)
}

func printTextResult(w io.Writer, res pageResult, verbose, useColor bool) {
	links := make([]linkResult, 0, len(res.links))
	if verbose {
		links = append(links, res.links...)
	} else {
		for _, l := range res.links {
			if l.err != nil {
				links = append(links, l)
			}
		}
		if len(links) == 0 {
			return
		}
	}
	sort.Slice(links, func(i, j int) bool {
		ei, ej := links[i].err != nil, links[j].err != nil
		if ei != ej {
			return !ei // successes first
		}
		si, sj := resultString(links[i]), resultString(links[j])
		if si != sj {
			return si < sj
		}
		return links[i].url < links[j].url
	})
	fmt.Fprintln(w, wrapColor("33", res.url, useColor))
	for _, l := range links {
		rs := resultString(l)
		code := "32"
		if l.err != nil {
			code = "31"
		}
		colored := wrapColor(code, rs, useColor)
		if l.url == "" {
			fmt.Fprintf(w, "\t%s\n", colored)
		} else {
			fmt.Fprintf(w, "\t%s\t%s\n", colored, l.url)
		}
	}
}

// JSON output.
type jsonLink struct {
	URL    string `json:"url"`
	Status int    `json:"status,omitempty"`
	Error  string `json:"error,omitempty"`
}
type jsonPage struct {
	URL   string     `json:"url"`
	Links []jsonLink `json:"links"`
}

func printJSONResults(w io.Writer, all []pageResult, verbose bool) {
	pages := []jsonPage{}
	for _, res := range all {
		links := []jsonLink{}
		hasErr := false
		for _, l := range res.links {
			if l.err != nil {
				hasErr = true
				links = append(links, jsonLink{URL: l.url, Error: l.err.Error()})
			} else if verbose {
				links = append(links, jsonLink{URL: l.url, Status: l.status})
			}
		}
		if verbose {
			// Rebuild in original order including successes.
			links = []jsonLink{}
			for _, l := range res.links {
				if l.err != nil {
					links = append(links, jsonLink{URL: l.url, Error: l.err.Error()})
				} else {
					links = append(links, jsonLink{URL: l.url, Status: l.status})
				}
			}
		}
		if !verbose && !hasErr {
			continue
		}
		pages = append(pages, jsonPage{URL: res.url, Links: links})
	}
	data, _ := json.Marshal(pages)
	fmt.Fprintln(w, string(data))
}

// JUnit output.
type junitFailure struct {
	Message string `xml:"message,attr"`
}
type junitCase struct {
	Name      string        `xml:"name,attr"`
	Classname string        `xml:"classname,attr"`
	Failure   *junitFailure `xml:"failure,omitempty"`
}
type junitSuite struct {
	Name     string      `xml:"name,attr"`
	Tests    int         `xml:"tests,attr"`
	Failures int         `xml:"failures,attr"`
	Skipped  int         `xml:"skipped,attr"`
	Cases    []junitCase `xml:"testcase"`
}
type junitSuites struct {
	XMLName xml.Name     `xml:"testsuites"`
	Suites  []junitSuite `xml:"testsuite"`
}

func printJUnitResults(w io.Writer, all []pageResult) {
	suites := junitSuites{}
	for _, res := range all {
		suite := junitSuite{Name: res.url, Tests: len(res.links)}
		for _, l := range res.links {
			tc := junitCase{Name: l.url, Classname: res.url}
			if l.err != nil {
				suite.Failures++
				tc.Failure = &junitFailure{Message: l.err.Error()}
			}
			suite.Cases = append(suite.Cases, tc)
		}
		suites.Suites = append(suites.Suites, suite)
	}
	data, _ := xml.MarshalIndent(suites, "", "  ")
	fmt.Fprint(w, xml.Header)
	fmt.Fprintln(w, string(data))
}
EOF
