func parseResponseHead(data, peek []byte) (int, []headerPair, error) {
	text := strings.ReplaceAll(string(data), "\r\n", "\n")
	lines := strings.Split(text, "\n")
	firstLine := ""
	if len(lines) > 0 {
		firstLine = lines[0]
	}
	wsIdx := strings.Index(firstLine, " ")
	if wsIdx < 0 {
		return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: cannot find whitespace in the first line of response %s. Buffer size=%d, contents: %s", formatBufferForError(peek), len(peek), formatBufferForError(peek))}
	}
	rest := firstLine[wsIdx+1:]
	// Parse status digits immediately after the single space.
	i := 0
	for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
		i++
	}
	if i == 0 {
		msg := "unexpected first char found. Expecting 0-9"
		if len(rest) == 0 {
			msg = "empty integer"
		}
		return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: cannot parse response status code: %s. Response %s. Buffer size=%d, contents: %s", msg, formatBufferForError(peek), len(peek), formatBufferForError(peek))}
	}
	if i < len(rest) && rest[i] != ' ' {
		return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: unexpected char at the end of status code. Response %s. Buffer size=%d, contents: %s", formatBufferForError(peek), len(peek), formatBufferForError(peek))}
	}
	status64, perrStr := parseUintStrict(rest[:i])
	if perrStr != "" {
		return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: cannot parse response status code: %s. Response %s. Buffer size=%d, contents: %s", perrStr, formatBufferForError(peek), len(peek), formatBufferForError(peek))}
	}
	status := int(status64)

	var headers []headerPair
	sawFirstHeader := false
	for _, line := range lines[1:] {
		if line == "" {
			continue
		}
		if line[0] == ' ' || line[0] == '\t' {
			if !sawFirstHeader {
				return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: invalid headers, headers cannot start with space or tab. Buffer size=%d, contents: %s", len(peek), formatBufferForError(peek))}
			}
			if len(headers) > 0 {
				headers[len(headers)-1].value += " " + strings.Trim(line, " \t")
			}
			continue
		}
		colon := strings.Index(line, ":")
		if colon < 0 {
			return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: malformed MIME header: missing colon: %q. Buffer size=%d, contents: %s", line, len(peek), formatBufferForError(peek))}
		}
		key := line[:colon]
		if key == "" || strings.ContainsRune(key, '\t') {
			return 0, nil, &internalRetryError{err: fmt.Errorf("error when reading response headers: malformed MIME header line: %q. Buffer size=%d, contents: %s", line, len(peek), formatBufferForError(peek))}
