new_chunk=r'''func readChunkedBody(br *bufio.Reader, maxBody int) ([]byte, error) {
	var buf bytes.Buffer
	for {
		line, err := br.ReadString('\n')
		if err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			// A size line terminated by EOF without LF.
			if len(line) == 0 {
				return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
			}
		}
		if !strings.HasSuffix(line, "\r\n") {
			// The offending character is the first non-hex char (or the LF).
			bad := byte('\n')
			return nil, &internalRetryError{err: fmt.Errorf("invalid character %q after chunk size", rune(bad))}
		}
		sizeLine := strings.TrimSuffix(line, "\r\n")
		size, herr := parseHexPrefix(sizeLine)
		if herr != nil {
			return nil, &internalRetryError{err: herr}
		}
		if size == 0 {
			for {
				tl, terr := br.ReadString('\n')
				if terr != nil {
					if isNetTimeout(terr) {
						return nil, errTimeout
					}
					return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
				}
				if tl == "\r\n" || tl == "\n" {
					break
				}
			}
			return buf.Bytes(), nil
		}
		if maxBody > 0 && buf.Len()+size > maxBody {
			return nil, errBodyTooLarge
		}
		if _, err := io.CopyN(&buf, br, int64(size)); err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		// Expect CRLF at the end of the chunk.
		b1, err := br.ReadByte()
		if err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		if b1 != '\r' {
			return nil, &internalRetryError{err: errors.New("cannot find crlf at the end of chunk")}
		}
		b2, err := br.ReadByte()
		if err != nil {
			if isNetTimeout(err) {
				return nil, errTimeout
			}
			return nil, &internalRetryError{err: io.ErrUnexpectedEOF}
		}
		if b2 != '\n' {
			return nil, &internalRetryError{err: errors.New("cannot find crlf at the end of chunk")}
		}
	}
}

func parseHexPrefix(s string) (int, error) {
	v := 0
	n := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			goto done
		}
		v = v*16 + d
		n++
	}
done:
	if n == 0 {
		return 0, errors.New("empty hex number")
	}
	return v, nil
}

