var _ = http.MethodGet

// dialSocks5 establishes a TCP connection to targetAddr (host:port)
// through the SOCKS5 proxy described by rawURL.
func (c *webClient) dialSocks5(ctx context.Context, rawURL, targetAddr string) (net.Conn, *bufio.Reader, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return nil, nil, err
	}
	proxyAddr := u.Host
	var username, password string
	hasAuth := false
	if u.User != nil {
		hasAuth = true
		username = u.User.Username()
		password, _ = u.User.Password()
	}
	network := "tcp4"
	if h := u.Hostname(); h != "" {
		if ip := net.ParseIP(h); ip != nil && ip.To4() == nil {
			network = "tcp6"
		}
	}
	wrap := func(err error) error {
		return fmt.Errorf("socks connect %s %s->%s: %v", network, proxyAddr, targetAddr, err)
	}
	var d net.Dialer
	conn, err := d.DialContext(ctx, "tcp", proxyAddr)
	if err != nil {
		return nil, nil, wrap(err)
	}
	fail := func(err error) (net.Conn, *bufio.Reader, error) {
		conn.Close()
		return nil, nil, wrap(err)
	}
	if ra, ok := conn.RemoteAddr().(*net.TCPAddr); ok && ra.IP != nil {
		if ra.IP.To4() != nil {
			network = "tcp4"
		} else {
			network = "tcp6"
		}
	}
	// Greeting.
	methods := []byte{0}
	if hasAuth {
		methods = []byte{0, 2}
	}
	greeting := append([]byte{5, byte(len(methods))}, methods...)
	if _, err := conn.Write(greeting); err != nil {
		return fail(err)
	}
	var sel [2]byte
	if _, err := io.ReadFull(conn, sel[:]); err != nil {
		return fail(err)
	}
	if sel[0] != 5 {
		return fail(errors.New("unexpected protocol version " + strconv.Itoa(int(sel[0]))))
	}
	switch sel[1] {
	case 0:
		// No authentication.
	case 2:
		if !hasAuth {
			return fail(errors.New("username/password authentication required"))
		}
		if len(username) > 255 || len(password) > 255 {
			return fail(errors.New("username/password too long"))
		}
		msg := []byte{1, byte(len(username))}
		msg = append(msg, username...)
		msg = append(msg, byte(len(password)))
		msg = append(msg, password...)
		if _, err := conn.Write(msg); err != nil {
			return fail(err)
		}
		var ar [2]byte
		if _, err := io.ReadFull(conn, ar[:]); err != nil {
			return fail(err)
		}
		if ar[1] != 0 {
			return fail(errors.New("username/password authentication failed"))
		}
	case 255:
		return fail(errors.New("no acceptable authentication methods"))
	default:
		return fail(fmt.Errorf("unknown authentication method %d", sel[1]))
	}
	// CONNECT request.
	host, portStr, err := net.SplitHostPort(targetAddr)
	if err != nil {
		return fail(err)
	}
	port, err := strconv.Atoi(portStr)
	if err != nil {
		return fail(err)
	}
	msg := []byte{5, 1, 0}
	if ip := net.ParseIP(host); ip != nil {
		if ip4 := ip.To4(); ip4 != nil {
			msg = append(msg, 1)
			msg = append(msg, ip4...)
		} else {
			msg = append(msg, 4)
			msg = append(msg, ip...)
		}
	} else {
		if len(host) > 255 {
			return fail(errors.New("destination host name too long"))
		}
		msg = append(msg, 3, byte(len(host)))
		msg = append(msg, host...)
	}
	msg = append(msg, byte(port>>8), byte(port))
	if _, err := conn.Write(msg); err != nil {
		return fail(err)
	}
	var head [4]byte
	if _, err := io.ReadFull(conn, head[:]); err != nil {
		return fail(err)
	}
	if head[0] != 5 {
		return fail(errors.New("unexpected protocol version " + strconv.Itoa(int(head[0]))))
	}
	// Read the bound address.
	var addrLen int
	switch head[3] {
	case 1:
		addrLen = 4
	case 4:
		addrLen = 16
	case 3:
		var lb [1]byte
		if _, err := io.ReadFull(conn, lb[:]); err != nil {
			return fail(err)
		}
		addrLen = int(lb[0])
	default:
		return fail(fmt.Errorf("unknown address type %d", head[3]))
	}
	rest := make([]byte, addrLen+2)
	if _, err := io.ReadFull(conn, rest); err != nil {
		return fail(err)
	}
	if head[1] != 0 {
		return fail(errors.New(socksReplyMessage(head[1])))
	}
	return conn, bufio.NewReaderSize(conn, c.effectiveBufferSize()), nil
}

func socksReplyMessage(code byte) string {
	switch code {
	case 1:
		return "general SOCKS server failure"
	case 2:
		return "connection not allowed by ruleset"
	case 3:
		return "network unreachable"
	case 4:
		return "host unreachable"
	case 5:
		return "connection refused"
	case 6:
		return "TTL expired"
	case 7:
		return "command not supported"
	case 8:
		return "address type not supported"
	}
	return "unknown code: " + strconv.Itoa(int(code))
}

func proxyScheme(raw string) string {
	if i := strings.Index(raw, "://"); i >= 0 {
		return strings.ToLower(raw[:i])
	}
	return ""
}
