import sys;sys.path.insert(0,'/tmp')
from diffharness import *
import time
# diffharness has two servers with shared routes.

def timed(args,label):
    results=[]
    for bin in ['./executable','/tmp/ours/executable']:
        request_log.clear();a=[x.replace('{base}',base).replace('{base2}',base2).replace('{port}',str(port)).replace('{port2}',str(port2)) for x in args];st=time.time();p=subprocess.run([bin]+a,capture_output=True,text=True,timeout=30);results.append((round(time.time()-st,2),p.returncode,p.stdout,p.stderr,sorted(x[1] for x in request_log)))
    print(label,'REF',results[0][0],results[0][1],'OUR',results[1][0],results[1][1],'outmatch',sorted(results[0][2].splitlines())==sorted(results[1][2].splitlines()),'errmatch',results[0][3]==results[1][3],'reqmatch',results[0][4]==results[1][4])
    if sorted(results[0][2].splitlines())!=sorted(results[1][2].splitlines()) or results[0][3]!=results[1][3]: print(results)

def delayed(delay):
    def body(h): time.sleep(delay);return b""
    return (200,{"Content-Type":"text/plain"},body)
setr({
 "/":(200,{"Content-Type":"text/html"},''.join(f'<a href="/p{i}">x</a>' for i in range(4))),
 **{f"/p{i}":delayed(.4) for i in range(4)}
})
