{"command":"cat <<'EOF' > cookies.go
package main

import "strings"

// parseSetCookies extracts cookie segments from Set-Cookie response headers,
// keyed by segment name (a later segment with an existing name replaces the
// earlier one's value in place).
func (r *rawResponse) cookieSegments() []headerPair {
	var out []headerPair
	set := func(key, val string) {
		if key == "" {
			return
		}
		for i := range out {
			if out[i].key == key {
				out[i].value = val
				return
			}
		}
		out = append(out, headerPair{key: key, value: val})
	}
	for _, h := range r.headers {
		if !strings.EqualFold(h.key, "Set-Cookie") {
			continue
		}
		for _, part := range strings.Split(h.value, ";") {
			p := strings.TrimLeft(part, " \t")
			if strings.Trim(p, " \t") == "" {
				continue
			}
			eq := strings.Index(p, "=")
			var key, val string
			if eq < 0 {
				key = strings.Trim(p, " \t")
				if strings.Contains(key, "\"") {
					continue
				}
				val = ""
			} else {
				key = strings.Trim(p[:eq], " \t")
				val = strings.TrimRight(p[eq+1:], " \t")
				if len(val) > 0 && val[0] == '"' {
					// Whole-value quoted string with no inner quote.
					if len(val) < 2 || val[len(val)-1] != '"' || strings.Contains(val[1:len(val)-1], "\"") {
						continue
					}
					val = val[1 : len(val)-1]
				}
			}
			set(key, val)
		}
	}
	return out
}

// parseRequestCookieValue turns a Cookie header value into serialized
// segments ("key=value", or a bare token).
func parseRequestCookieValue(s string) []string {
	var out []string
	for _, part := range strings.Split(s, ";") {
		t := strings.Trim(part, " \t")
		if t == "" {
			continue
		}
		eq := strings.Index(t, "=")
		if eq < 0 {
			out = append(out, t)
			continue
		}
		key := strings.Trim(t[:eq], " \t")
		val := strings.Trim(t[eq+1:], " \t")
		if len(val) >= 2 && val[0] == '"' && val[len(val)-1] == '"' && !strings.Contains(val[1:len(val)-1], "\"") {
			val = val[1 : len(val)-1]
		}
		if key == "" {
			out = append(out, val)
		} else {
			out = append(out, key+"="+val)
		}
	}
	return out
}
