s=open('httpclient.go').read()
# Thread extra cookies through call chain: getRedirect, getRetry, getThrottled, doRaw, doOne, buildRequest
s=s.replace('resp, err := c.getRedirect(u, 0)','resp, err := c.getRedirect(u, 0, nil)')
# getRedirect replacement
start=s.index('func (c *webClient) getRedirect')
end=s.index('func isNetTimeout')
new='''func (c *webClient) getRedirect(u *url.URL, _ int, _ []headerPair) (*rawResponse, error) {
	if 0 > c.opts.MaxRedirections {
		return nil, errors.New("too many redirections")
	}
	var cumulative []headerPair
	var extra []headerPair
	resp, err := c.getRetry(u, extra)
	if err != nil {
		return nil, err
	}
	current := u
	count := 0
	for resp.status >= 300 && resp.status < 400 {
		loc := resp.headerFirst("Location")
		if loc == "" {
			return nil, errors.New("location header not set")
		}
		if count >= c.opts.MaxRedirections {
			return nil, errors.New("too many redirections")
		}
		next, perr := current.Parse(loc)
		if perr != nil {
			return nil, perr
		}
		next.Fragment = ""
		next.RawFragment = ""
		cumulative = append(cumulative, resp.cookieSegments()...)
		extra = append(extra, cumulative...)
		resp2, ferr := c.getRetry(next, extra)
		if ferr != nil {
			return nil, fmt.Errorf("%v (following redirect %s)", ferr, next.String())
		}
		resp = resp2
		current = next
		count++
	}
	return resp, nil
}

