#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct BrotliDecoderStateStruct BrotliDecoderState;
typedef int BrotliDecoderResult;
typedef void* (*brotli_alloc_func)(void*, size_t);
typedef void (*brotli_free_func)(void*, void*);

BrotliDecoderState* BrotliDecoderCreateInstance(brotli_alloc_func alloc_func,
                                                brotli_free_func free_func,
                                                void* opaque);
void BrotliDecoderDestroyInstance(BrotliDecoderState* state);
BrotliDecoderResult BrotliDecoderDecompressStream(
    BrotliDecoderState* state, size_t* available_in, const uint8_t** next_in,
    size_t* available_out, uint8_t** next_out, size_t* total_out);
int BrotliDecoderGetErrorCode(BrotliDecoderState* state);
const char* BrotliDecoderErrorString(int code);

int main(void) {
  BrotliDecoderState* state =
      BrotliDecoderCreateInstance(NULL, NULL, NULL);
  if (state == NULL) {
    fprintf(stderr, "RESERVED\n");
    return 1;
  }
  uint8_t inbuf[8192];
  uint8_t outbuf[8192];
  size_t available_in = 0;
  const uint8_t* next_in = NULL;
  BrotliDecoderResult result = 2; /* NEEDS_MORE_INPUT */
  while (result == 2 || result == 3) {
    if (result == 2 && available_in == 0) {
      size_t n = fread(inbuf, 1, sizeof(inbuf), stdin);
      if (n == 0) {
        break;
      }
      available_in = n;
      next_in = inbuf;
    }
    size_t available_out = sizeof(outbuf);
    uint8_t* next_out = outbuf;
    result = BrotliDecoderDecompressStream(
        state, &available_in, &next_in, &available_out, &next_out, NULL);
    size_t produced = sizeof(outbuf) - available_out;
    if (produced > 0) {
      fwrite(outbuf, 1, produced, stdout);
    }
    if (result == 0) {
      int code = BrotliDecoderGetErrorCode(state);
      const char* msg = BrotliDecoderErrorString(code);
      fprintf(stderr, "%s\n", msg != NULL ? msg : "RESERVED");
      BrotliDecoderDestroyInstance(state);
      return 1;
    }
  }
  {
    int code = BrotliDecoderGetErrorCode(state);
    if (result != 1) {
      const char* msg = BrotliDecoderErrorString(code);
      /* A truncated stream at EOF is reported like other corrupt input by
         the reference decoder; use its message when available. */
      if (code != 0 && msg != NULL) {
        fprintf(stderr, "%s\n", msg);
      } else {
        fprintf(stderr, "UNREACHABLE\n");
      }
      BrotliDecoderDestroyInstance(state);
      return 1;
    }
  }
  BrotliDecoderDestroyInstance(state);
  return 0;
}
EOF
