{"command":"cat <<'EOF' > urlcompat.go
package main

import (
	"net/url"
	"strings"
)

// Newer Go releases reject some bracketed hosts that older releases (and
// the reference) accepted as host names. These helpers fall back to a
// placeholder host during parsing and restore the original host text.

func bracketHostReplacement(raw string) (string, string, bool) {
	authStart := -1
	if strings.HasPrefix(raw, "//") {
		authStart = 2
	} else if i := strings.Index(raw, "://"); i >= 0 {
		authStart = i + 3
	} else {
		return "", "", false
	}
	authEnd := len(raw)
	for i := authStart; i < len(raw); i++ {
		if raw[i] == '/' || raw[i] == '?' || raw[i] == '#' {
			authEnd = i
			break
		}
	}
	authority := raw[authStart:authEnd]
	hostStart := 0
	if at := strings.LastIndex(authority, "@"); at >= 0 {
		hostStart = at + 1
	}
	if hostStart >= len(authority) || authority[hostStart] != '[' {
		return "", "", false
	}
	closeRel := strings.Index(authority[hostStart:], "]")
	if closeRel < 0 {
		return "", "", false
	}
	closeIdx := hostStart + closeRel
	origHostPort := authority[hostStart:]
	replacedAuth := authority[:hostStart] + "[::1]" + authority[closeIdx+1:]
	return raw[:authStart] + replacedAuth + raw[authEnd:], origHostPort, true
}

func isBracketHostParseError(err error) bool {
	if err == nil {
		return false
	}
	s := err.Error()
	return strings.Contains(s, "invalid host:") || strings.Contains(s, "invalid IP-literal")
}

func parseURL(raw string) (*url.URL, error) {
	u, err := url.Parse(raw)
	if err == nil || !isBracketHostParseError(err) {
		return u, err
	}
	replaced, orig, ok := bracketHostReplacement(raw)
	if !ok {
		return nil, err
	}
	u2, err2 := url.Parse(replaced)
	if err2 != nil {
		return nil, err
	}
	u2.Host = orig
	return u2, nil
}

func parseURLRef(base *url.URL, raw string) (*url.URL, error) {
	u, err := base.Parse(raw)
	if err == nil || !isBracketHostParseError(err) {
		return u, err
	}
	replaced, orig, ok := bracketHostReplacement(raw)
	if !ok {
		return nil, err
	}
	u2, err2 := base.Parse(replaced)
	if err2 != nil {
		return nil, err
	}
	u2.Host = orig
	return u2, nil
}
