import socket,threading,subprocess,struct,time,sys
sys.path.insert(0,'/tmp');from harness import *
srv,hport=make_server();routes.update({"/":(200,{"Content-Type":"text/html"},"ok")})
delay=[0]
def parse_q(data):
 off=12;labs=[]
 while data[off]!=0:
  ln=data[off];labs.append(data[off+1:off+1+ln]);off+=1+ln
 off+=1;q=struct.unpack('>H',data[off:off+2])[0];return data[:2],q,off+4
s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);s.bind(('127.0.0.1',0));dport=s.getsockname()[1]
def loop():
 while True:
  data,a=s.recvfrom(4096);tid,q,qend=parse_q(data);time.sleep(delay[0]);an=1 if q==1 else 0;ans=b'\xc0\x0c'+struct.pack('>HHI',1,1,0)+struct.pack('>H',4)+socket.inet_aton('127.0.0.1') if an else b'';s.sendto(tid+struct.pack('>HHHHH',0x8180,1,an,0,0)+data[12:qend]+ans,a)
threading.Thread(target=loop,daemon=True).start()
for bin in ['./executable','/tmp/ours/executable']:
 for delayv,t in [(2,'1'),(2,'0'),(.5,'1'),(7,'10')]:
  delay[0]=delayv;st=time.time();p=subprocess.run([bin,f'--dns-resolver=127.0.0.1:{dport}',f'--timeout={t}',f'http://example.test:{hport}/'],capture_output=True,text=True,timeout=20);print(bin,'delay',delayv,'timeout',t,round(time.time()-st,2),p.returncode,p.stderr.strip(),p.stdout.strip())
