	if strings.Contains(hostname, "%") {
		if taddr, rerr := net.ResolveTCPAddr("tcp", net.JoinHostPort(hostname, portStr)); rerr == nil {
			var d net.Dialer
			conn, derr := d.DialContext(ctx, "tcp", taddr.String())
			if derr != nil {
				return nil, fmt.Errorf("error when dialing %s: %w", taddr.String(), derr)
			}
			return conn, nil
		}
	}
	ips, err := c.resolveHost(ctx, hostname)
	if err != nil {
		return nil, err
	}
	port, _ := strconv.Atoi(portStr)
	type dialResult struct {
		idx  int
		conn net.Conn
		err  error
		addr string
	}
	dctx, cancel := context.WithCancel(ctx)
	defer cancel()
	results := make(chan dialResult, len(ips))
	for i, ip := range ips {
		go func(i int, ip net.IP) {
			addr := &net.TCPAddr{IP: ip, Port: port}
			var d net.Dialer
			conn, derr := d.DialContext(dctx, "tcp", addr.String())
			results <- dialResult{idx: i, conn: conn, err: derr, addr: addr.String()}
		}(i, ip)
	}
	errs := make([]error, len(ips))
	for remaining := len(ips); remaining > 0; remaining-- {
		r := <-results
		if r.err == nil {
			// Close any late successful connections and abort pending dials.
			go func(left int) {
				for i := 0; i < left; i++ {
					lr := <-results
					if lr.conn != nil {
						lr.conn.Close()
					}
				}
			}(remaining - 1)
			cancel()
			return r.conn, nil
		}
		errs[r.idx] = fmt.Errorf("error when dialing %s: %w", r.addr, r.err)
	}
	for _, e := range errs {
		if e != nil {
			return nil, e
		}
	}
	return nil, errors.New("missing port in address")
}

